Ceviri.ekle("bn","olay",{
"OLAYLAR_EK8:1637-06-18:0":{"b": ["আজাক দুর্গের দন কসাকদের হাতে হারানো", "ba068b2f"], "d": ["দন কসাকরা 21 এপ্রিল 1637 তারিখে অবরোধ করা আজাক দুর্গ দুই মাস পর দখল করলো; কৃষ্ণসাগরের উত্তর-পূর্ব দরজা ও দন বাণিজ্যের তালা হওয়া দুর্গ প্রথমবার অটোমান হাত থেকে বেরিয়ে গেল। TDV ইসলাম বিশ্বকোষের আজাক ভুক্তি অনুযায়ী কসাকরা দুর্গ 1637 সালে দখল করলো, 1641 সালে দেলি হুসেইন পাশার নেতৃত্বে তিন মাস স্থায়ী বড় অবরোধ প্রতিহত করলো এবং কেবল 1642 সালে ক্রিমিয়ার খান মেহমেদ গিরায়ের আগমনে দুর্গ খালি করলো। রাষ্ট্র তখন বাগদাদ ফ্রন্ট নিয়ে ব্যস্ত ছিল; দুর্গ পাঁচ বছর ধরে রাখতে না পারা কৃষ্ণসাগরের 'অটোমান হ্রদ' হওয়ার বৈশিষ্ট্যের প্রথম ফাটল।", "da9b9fd8"]},
"OLAYLAR_EK8:1657-11-15:0":{"b": ["লিমনোস ও সামোথ্রাকির পুনরুদ্ধার", "c445553b"], "d": ["বোজজাআদার 31 আগস্ট 1657 তারিখে উদ্ধারের পর কোপরুলু মেহমেদ পাশা নৌবহরকে উত্তরে চালিত করলেন এবং ভেনিসের ষোলো মাস ধরে দখলে রাখা লিমনোস ও সামোথ্রাকি পুনরুদ্ধার করলেন। TDV ইসলাম বিশ্বকোষের লিমনি ভুক্তি অনুযায়ী দ্বীপ 1656 সালের জুলাইয়ে ভেনিসের হাতে গিয়েছিল, 1657 সালের নভেম্বরে পুনরুদ্ধার হলো। এভাবে দার্দানেলিস প্রণালীর মুখে ভেনিসীয় অবরোধ সম্পূর্ণ ভেঙে গেল এবং ইস্তানবুলের শস্যপথ আবার নিরাপদ হলো; প্রধান উজিরের অসাধারণ ক্ষমতা নিয়ে আসা প্রথম বছরের সবচেয়ে বাস্তব অর্জন এটি।", "9a57630d"]},
"OLAYLAR_EK8:1688-09-11:0":{"b": ["কনিনের ভেনিসের হাতে হারানো — 166 বছরের দালমাতিয়া সীমান্ত দুর্গের পতন", "252406b7"], "d": ["1683 ভিয়েনা বিপর্যয়ের পর বহু ফ্রন্টে খোলা যুদ্ধে ভেনিসীয় বাহিনী দালমাতিয়ার অভ্যন্তরে অগ্রসর হলো। দালমাতিয়া জেনারেল জিরোলামো কর্নারোর অবরোধ করা কনিন বারো দিনের অবরোধের পর বেইলারবেই মেহমেদ পাশার আত্মসমর্পণ করলো। কনিন 1522 সালে গাজি হুসরেভ বের বিজয় করা এবং 166 বছর অটোমান হাতে থাকা দালমাতিয়া সীমান্ত রেখার প্রধান দুর্গ ছিল; এর হারানো অঞ্চলকে বহুলাংশে ভেনিসের জন্য খুলে দিল।", "d4aa761c"]},
"OLAYLAR_EK8:1779-04-01:0":{"b": ["বসরার ইরানি দখল থেকে পুনরুদ্ধার", "5b10c5c1"], "d": ["কেরিম খান জেন্দের ভাই সাদিক খানের 1776 সালে দখল করা বসরা কেরিম খানের 2 মার্চ 1779 তারিখে মৃত্যুর পর ইরানে সিংহাসন কলহ শুরু হলে খালি করা হলো; সাদিক খান সালতানাতের দাবি নিয়ে ইরানে ফিরলেন। শহর অল্প সময় মুনতেফিক গোত্রের হাতে থাকার পর আবার অটোমান শাসনে এলো। শিরাজ থেকে ফেরা সাবেক মুতেসেল্লিম সুলাইমান আগা বসরার গভর্নরত্ব চাইলেন এবং বুয়ুক সুলাইমান পাশা নামে বসরা, বাগদাদ ও শেহরিজোরের গভর্নর হলেন। উপসাগরীয় বাণিজ্য অটোমান নিয়ন্ত্রণে ফিরলো; দখলের বছরগুলোতে বাণিজ্যের একাংশ কুয়েতে সরে গিয়েছিল এবং 1778 সাল থেকে মরু ডাকও কুয়েত থেকে ছাড়া হচ্ছিল।", "2f14ff54"]},
"OLAYLAR_EK8:1793-01-01:0":{"b": ["তৈমুর শাহের মৃত্যু, জামান শাহের সিংহাসনারোহণ (দুররানি রাষ্ট্র)", "c3effdb2"], "d": ["বিশ বছরের বেশি সময় দেশকে ভেতর থেকে সুসংহত করা তৈমুর শাহের মৃত্যুতে কান্দাহার-হেরাত-কাবুলের গভর্নর তিন ভাই সিংহাসনের জন্য কলহ করলেন; রাজধানী হাতে রাখা কাবুলের গভর্নর জামান শাহ 20 মে 1793 তারিখে শাহ হলেন। এই উত্তরাধিকার সংকট রাজবংশের বিভক্তি প্রক্রিয়ার কার্যত সূচনা।", "4b3d7d19"]},
"OLAYLAR_EK8:1819-11-01:0":{"b": ["ʻAi Noa — হাওয়াইয়ে ঐতিহ্যবাহী কাপু ব্যবস্থার অবসান", "0b10e1d8"], "d": ["প্রথম কামেহামেহার মৃত্যুর ছয় মাস পর নতুন রাজা লিহোলিহো মা কাআহুমানুর সমর্থনে নারী-পুরুষের আলাদা খাওয়ার নিষেধাজ্ঞা (ʻaikapu) ইচ্ছাকৃতভাবে ভাঙলেন। 'ʻAi Noa' (মুক্ত খাওয়া) নামে পরিচিত এই কাজ ঐতিহ্যবাহী কাপু ধর্ম-আইন ব্যবস্থা আনুষ্ঠানিকভাবে শেষ করলো; দ্বীপগুলোর পুরনো মন্দির (heiau) অল্প সময়ে ভাঙা হলো। এটি পশ্চিমা মিশনারিদের আগমনের (1820) আগের সবচেয়ে বড় ধর্মীয়-রাজনৈতিক ভাঙন।", "7f6d4463"]},
"OLAYLAR_EK8:1830-02-03:0":{"b": ["লন্ডন প্রটোকল — গ্রিসের স্বাধীনতার স্বীকৃতি", "4c7b4b72"], "d": ["ব্রিটেন, ফ্রান্স ও রাশিয়ার লন্ডনে স্বাক্ষরিত প্রটোকল এদির্ন চুক্তির প্রস্তাবিত স্বায়ত্তশাসন ছাড়িয়ে গ্রিসকে স্বাধীন রাষ্ট্র হিসেবে স্বীকৃতি দিল। বিধানগুলো: মোরা উপদ্বীপ, আত্তিকা ও ইউবোয়া এবং সাইক্লাডিস দ্বীপপুঞ্জ নতুন রাষ্ট্রকে ছেড়ে দেওয়া হলো; সীমানা আর্তা-ভোলোস রেখায় টানা হলো; অটোমান রাষ্ট্রকে ক্ষতিপূরণ দেওয়া স্থির হলো; রাষ্ট্রের শাসনরূপ 'স্বাধীন রাজতন্ত্র' নির্ধারিত হলো। এটি সাম্রাজ্য থেকে বিচ্ছিন্ন প্রথম স্বাধীন রাষ্ট্র এবং পরবর্তী বলকান স্বাধীনতাগুলোর আইনি নজির স্থাপন করেছে। লন্ডন প্রটোকলে স্বাধীনতা স্বীকৃত গ্রিসের সঙ্গে সাইক্লাডিস দ্বীপপুঞ্জ (নাক্সোস, ইস্তেন্দিল, সান্তোরিনি, পারোস, দেগিরমেনলিক, সিরোস, মাইকোনোস প্রভৃতি) যুক্ত হলো।", "920bfab9"]},
"OLAYLAR_EK8:1835-01-01:0":{"b": ["আবদুল্লাহ ইবনে রশিদ হাইল আমিরাত দখল করলেন — শাম্মার (রশিদি) রাজবংশের প্রতিষ্ঠা", "fb513b8a"], "d": ["1818 সালে মেহমেদ আলী পাশার বাহিনীর দিরইয়া পতনের মাধ্যমে জাবালে শাম্মার অঞ্চল সউদি আধিপত্য থেকে বেরিয়ে গেল এবং আমিরাত ইবনে আলী পরিবারের হাতে থাকলো। অটোমান আধিপত্য পুনঃপ্রতিষ্ঠার সমর্থক আবদুল্লাহ ইবনে রশিদ ভাই উবাইদের সঙ্গে ইবনে আলী পরিবারের বিরুদ্ধে শুরু করা সংগ্রাম 1835 সালে জিতে হাইল আমিরাত দখল করলেন এবং রশিদি রাজবংশের আধিপত্য স্থাপন করলেন।", "631e33a9"]},
"OLAYLAR_EK8:1840-10-08:0":{"b": ["হাওয়াইয়ের প্রথম লিখিত সংবিধান ঘোষিত", "401a8a1d"], "d": ["রাজ্যের প্রথম পূর্ণাঙ্গ লিখিত সংবিধান ঘোষিত হলো; রাজার ক্ষমতা সীমিতকারী, প্রতিনিধিত্বমূলক পরিষদ গঠনকারী এই দলিল হাওয়াইকে সাংবিধানিক রাজতন্ত্রে রূপান্তরিত করলো।", "a32cdab2"]},
"OLAYLAR_EK8:1887-07-06:0":{"b": ["বেয়নেট সংবিধান — রাজা কালাকাউয়ার ক্ষমতা ছাঁটা", "4953363b"], "d": ["একটি সশস্ত্র মিলিশিয়া দল রাজা কালাকাউয়াকে ভয় দেখিয়ে রাজ্যের ক্ষমতা বহুলাংশে ছাঁটা নতুন সংবিধানে স্বাক্ষর করতে বাধ্য করলো; দলিলটি 'বেয়নেট সংবিধান' (Bayonet Constitution) নামে পরিচিত এবং সিংহাসন কার্যত শ্বেতাঙ্গ অভিবাসী অভিজাতদের নিয়ন্ত্রণে নিয়ে গেল।", "cc95eabb"]},
"OLAYLAR_EK8:1893-02-18:0":{"b": ["প্রথম জর্জ তুপৌর মৃত্যু, দ্বিতীয় জর্জ তুপৌর সিংহাসনারোহণ (টোঙ্গা)", "b56e2b32"], "d": ["প্রতিষ্ঠাতা রাজা প্রথম জর্জ তুপৌর মৃত্যুতে প্রপৌত্র দ্বিতীয় জর্জ তুপৌ সিংহাসনে বসলেন; অভিষেক অনুষ্ঠান 17 মার্চ 1893 তারিখে নুকুআলোফায় অনুষ্ঠিত হলো।", "01fe9fa1"]},
"OLAYLAR_EK8:1893-09-19:0":{"b": ["নিউজিল্যান্ড নারীদের ভোটাধিকার দেওয়া প্রথম স্বশাসিত দেশ হলো", "0d277cde"], "d": ["গভর্নর লর্ড গ্লাসগো স্বাক্ষরিত নতুন নির্বাচন আইনের মাধ্যমে নিউজিল্যান্ড নারীদের সংসদ নির্বাচনে ভোটাধিকার দেওয়া বিশ্বের প্রথম স্বশাসিত দেশ হলো।", "ba9b7f63"]},
"OLAYLAR_EK8:1894-07-04:0":{"b": ["হাওয়াই প্রজাতন্ত্র ঘোষিত", "4346bd5d"], "d": ["1893 সালে রানি লিলিউওকালানিকে উৎখাতকারী ষড়যন্ত্রকারীরা অস্থায়ী সরকারকে আনুষ্ঠানিক প্রজাতন্ত্রে রূপান্তরিত করলো; স্যানফোর্ড ডোল রাষ্ট্রপতি ঘোষিত হলেন। এই মধ্যবর্তী শাসন 1898 সালের মার্কিন অন্তর্ভুক্তি পর্যন্ত চললো।", "d1a76858"]},
"OLAYLAR_EK8:1901-06-11:0":{"b": ["নিউজিল্যান্ডের সীমানা কুক দ্বীপপুঞ্জ ও নিউয়েকে অন্তর্ভুক্ত করে প্রসারিত হলো", "d0370a33"], "d": ["নিউজিল্যান্ডের সীমানা কুক দ্বীপপুঞ্জ (রারোতোঙ্গা, আইতুতাকি ও দক্ষিণ দ্বীপপুঞ্জসহ উত্তর কুক দ্বীপপুঞ্জ) ও নিউয়েকে অন্তর্ভুক্ত করে প্রসারিত হলো; এই দ্বীপগুলো নিউজিল্যান্ডের সঙ্গে যুক্ত অঞ্চল হলো।", "464148bd"]},
"OLAYLAR_EK8:1918-04-05:0":{"b": ["দ্বিতীয় জর্জ তুপৌর মৃত্যু, সালোতে তুপৌ তৃতীয়র সিংহাসনারোহণ (টোঙ্গা)", "a3084f3b"], "d": ["দ্বিতীয় জর্জ তুপৌ যক্ষ্মায় মারা গেলেন; 18 বছর বয়সী কন্যা সালোতে পরদিন রানি ঘোষিত হলেন, অভিষেক অনুষ্ঠান 11 অক্টোবর 1918 তারিখে অনুষ্ঠিত হলো।", "a63672b5"]},
"OLAYLAR_EK8:1920-04-26:0":{"b": ["খোরেজম গণপ্রজাতন্ত্র ঘোষিত", "0a6b79f9"], "d": ["1917 অক্টোবর বিপ্লবের পর খিভার খানের উৎখাতের পর খোরেজম গণপ্রজাতন্ত্র ঘোষিত হলো।", "1934b071"]},
"OLAYLAR_EK8:1920-08-10:0":{"b": ["সেভ্র চুক্তি — সাম্রাজ্যের ভাগাভাগির পাঠ্য", "64980d7b"], "d": ["অটোমান সরকারের মিত্রশক্তির সঙ্গে স্বাক্ষর করা এবং সাম্রাজ্যকে কার্যত বিলুপ্তকারী পাঠ্য। বিধানগুলো: পূর্ব থ্রেস ও ইজমির অঞ্চল গ্রিসকে; পূর্ব আনাতোলিয়ায় স্বাধীন আর্মেনিয়া ও স্বায়ত্তশাসিত কুর্দিস্তান পরিকল্পিত হলো; সিরিয়া ফ্রান্সকে, ইরাক ও ফিলিস্তিন ব্রিটেনকে ম্যান্ডেট হিসেবে ছেড়ে দেওয়া হলো; প্রণালী আন্তর্জাতিক কমিশনকে হস্তান্তরিত হলো; সেনাবাহিনী 50.700 জনে নামানো হলো, ক্যাপিটুলেশন ফিরে এলো, অর্থ ব্যবস্থা মিত্রশক্তির নিয়ন্ত্রণে দেওয়া হলো। আঙ্কারার গ্র্যান্ড ন্যাশনাল অ্যাসেম্বলি চুক্তিটি আদৌ স্বীকার করলো না এবং স্বাক্ষরকারীদের দেশদ্রোহী ঘোষণা করলো; পাঠ্য কার্যকর হলো না, 1923 সালে লোজান তার জায়গা নিল। মানচিত্রে এর কোনো প্রতিফলন না থাকার কারণ এটাই — সেভ্র আইনত কখনো প্রয়োগ হয়নি।", "c9b2648b"]},
"OLAYLAR_EK8:1920-09-02:0":{"b": ["লালফৌজ বুখারা শহরে প্রবেশ করলো — শেষ আমির আলিম খান সিংহাসনচ্যুত", "f8f5bfcf"], "d": ["লালফৌজ 2 সেপ্টেম্বর 1920 তারিখে বুখারা শহরে প্রবেশ করলো এবং শেষ মাংগিত আমির আলিম খান সিংহাসনচ্যুত হলেন। আমির দেশের পূর্বে দুশানবেতে সরে গেলেন এবং আধা বছর সেখান থেকে সোভিয়েতদের বিরুদ্ধে লড়াই পরিচালনা করলেন; লালফৌজ দুশানবে 21 ফেব্রুয়ারি 1921 তারিখে দখল করলো, আমির আরও পূর্বে এবং সেখান থেকে আফগানিস্তানে গেলেন। আমিরাত আনুষ্ঠানিকভাবে 6 অক্টোবর 1920 তারিখে বিলুপ্ত হলো (দ্রষ্টব্য বুখারা গণ সোভিয়েত প্রজাতন্ত্র)।", "19580033"]},
"OLAYLAR_EK8:1920-10-08:0":{"b": ["বুখারা গণ সোভিয়েত প্রজাতন্ত্র ঘোষিত", "ef579627"], "d": ["লালফৌজের 28-31 আগস্ট 1920 তারিখে বুখারা আমিরাত ভেঙে আমির আলিম খানকে পূর্ব বুখারায় পালাতে বাধ্য করার পর ফয়জুল্লা খোজায়েভের নেতৃত্বে বুখারা গণ সোভিয়েত প্রজাতন্ত্র ঘোষিত হলো।", "690bfb2f"]},
"OLAYLAR_EK8:1921-08-14:0":{"b": ["তান্নু তুভা গণপ্রজাতন্ত্র স্বাধীনতা ঘোষণা করলো", "8710ea3d"], "d": ["তুভান পিপলস রেভোলিউশনারি পার্টির নেতৃত্বে স্বাধীনতা ঘোষিত হলো; প্রথম সংবিধানের প্রথম ধারায় বলা ছিল রাষ্ট্র 'আন্তর্জাতিক সম্পর্কে সোভিয়েত রাশিয়ার আশ্রয়ে' কাজ করবে। এই ঘটনার ফলে কিজিল (বেলোৎসারস্ক, তান্নু-তুভা) তান্নু-তুভা গণপ্রজাতন্ত্রে গেল।", "dc0ac64a"]},
"OLAYLAR_EK8:1921-09-01:0":{"b": ["বুখারা গণ সোভিয়েত প্রজাতন্ত্রের নতুন সংবিধান গৃহীত", "fb17bf39"], "d": ["রুশ 1918 সংবিধানের বিপরীতে ব্যক্তিগত ভূমি/উৎপাদন মালিকানার অনুমতি দেওয়া এবং অ-প্রলেতারিয়দেরও ভোটাধিকার দেওয়া এক নতুন সংবিধান গৃহীত হলো (ক্ষমতাচ্যুত আমিরের আত্মীয় ও বড় জমিদার ব্যতীত)।", "91bf1a32"]},
"OLAYLAR_EK8:1921-09-05:0":{"b": ["খোরেজম সোভিয়েত সমাজতান্ত্রিক প্রজাতন্ত্রে রূপান্তর", "14a1d26f"], "d": ["দেশ নাম ও মর্যাদা বদলে খোরেজম সোভিয়েত সমাজতান্ত্রিক প্রজাতন্ত্র হলো; প্রশাসনিক-আইনি কাঠামো সোভিয়েত ব্যবস্থা অনুযায়ী পুনর্বিন্যস্ত হলো।", "e3e9b939"]},
"OLAYLAR_EK8:1922-03-03:0":{"b": ["তান্নু তুভা সরকার কার্যত দায়িত্ব শুরু করলো", "22ea1516"], "d": ["1922 সালের ফেব্রুয়ারিতে প্রথম দলীয় সভার পর গঠিত সরকার কার্যত দায়িত্ব শুরু করলো।", "3b3c6c39"]},
"OLAYLAR_EK8:1923-10-12:0":{"b": ["তান্নু তুভার প্রথম মহা কুরুলতাই বসলো", "80fe15f2"], "d": ["দেশের প্রথম মহা কুরুলতাই (গণপরিষদ) বসলো; এটি রাষ্ট্রের প্রাতিষ্ঠানিকীকরণ প্রক্রিয়ার প্রথম বড় প্রতিনিধিত্বমূলক সভা।", "e8cf06ac"]},
"OLAYLAR_EK8:1924-01-01:0":{"b": ["খোরেজম সোভিয়েত সমাজতান্ত্রিক প্রজাতন্ত্র ও বুখারা গণ সোভিয়েত প্রজাতন্ত্রের জাতীয় সীমানা নির্ধারণে অবসান — উজবেকিস্তান/তুর্কমেনিস্তান সোভিয়েত প্রজাতন্ত্র গঠন", "e8c8ab4f"], "d": ["সোভিয়েত 'জাতীয় সীমানা নির্ধারণ' (natsionalno-territorialnoe razmezhevanie) সিদ্ধান্তে খোরেজম সোভিয়েত সমাজতান্ত্রিক প্রজাতন্ত্র ও বুখারা গণ সোভিয়েত প্রজাতন্ত্র বিলুপ্ত হলো; তাদের ভূখণ্ড নতুন গঠিত উজবেকিস্তান ও তুর্কমেনিস্তান সোভিয়েত সমাজতান্ত্রিক প্রজাতন্ত্রের মধ্যে ভাগ করা হলো (খিভার পূর্ব অংশ উজবেকিস্তানে, পশ্চিম অংশ তুর্কমেনিস্তানে)। TDV-এর `harizm` ভুক্তি: '1924’te Hîve Hanlığı’nın doğu kesimleri Özbekistan Sovyet Sosyalist Cumhuriyeti’ne, batı tarafı da Türkmenistan Sovyet Sosyalist Cumhuriyeti’ne bırakıldı.' — কেবল বছর দেয়।", "58053c38"]},
"OLAYLAR_EK9:1427-01-01:0":{"b": ["আলাইয়ার মামলুক সুলতান বারসবাইয়ের কাছে বিক্রি", "c8bd35f2"], "d": ["1293 সালে কারামানোগলু মেচদুদ্দিন মাহমুদ বে দখল করা আলাইয়া কারামানোগলুদের এক শাখা শাসিত আলাদা বেগলিকে পরিণত হয়েছিল; ইবনে বতুতা 1333 সালে প্রশাসন কারামানোগলু ইউসুফ বের হাতে ছিল বলে লিখেছেন। কারামান ইবনে সাভজি বে 1427 সালে শহর পাঁচ হাজার স্বর্ণমুদ্রার বিনিময়ে মামলুক সুলতান বারসবাইয়ের কাছে বিক্রি করলেন এবং আলাইয়া মামলুক শাসনে এলো। ভূমধ্যসাগরের এই প্রধান বন্দর এভাবে অটোমানদের দক্ষিণে খোলা পথে মামলুক হাতে বাধা হলো; 1471 সালে গেদিক আহমেদ পাশা অবরোধ করলে শেষ বে কিলিচআরসলান শহর আত্মসমর্পণ করলেন।", "9be5efe7"]},
"OLAYLAR_EK9:1741-06-12:0":{"b": ["তাবারকার জেনোয়াবাসীদের কাছ থেকে দখল — লোমেল্লিনি প্রবাল সুবিধার অবসান", "b1f33eb5"], "d": ["পঞ্চম চার্লসের 1544 সালে তিউনিসের বের সঙ্গে করা চুক্তির পর জেনোয়ার লোমেল্লিনি পরিবার তাবারকা দ্বীপে বসতি স্থাপন করে দুইশ বছর প্রবাল সুবিধা নিজেদের হাতে রেখেছিল; দ্বীপ অটোমান তিউনিসের মাঝখানে খ্রিস্টান বাণিজ্য ঘাঁটি হিসেবে থেকে গিয়েছিল। হুসাইনি রাজবংশের আলী পাশা পরিবারের দ্বীপ হাতছাড়া করার প্রচেষ্টার খবর পেয়ে বাহিনী পাঠালেন এবং 12 জুন 1741 তারিখে দ্বীপ দখল করলেন; পনেরোশ-এর মতো খ্রিস্টানকে তিউনিসে স্থানান্তর করা হলো। তাবারকা এই তারিখের পর তিউনিস ওজাকের শাসনে এলো।", "93c8bd7b"]},
"OLAYLAR_EK9:1798-07-21:0":{"b": ["পিরামিডের যুদ্ধ ও কায়রোর ফরাসিদের হাতে দখল", "3ddd6b96"], "d": ["নেপোলিয়ন আলেকজান্দ্রিয়া থেকে নীল বরাবর দক্ষিণে অগ্রসর হলেন এবং 21 জুলাই 1798 তারিখে গিজার বিপরীতে ইমবাবায় মুরাদ বের মামলুক অশ্বারোহীর মুখোমুখি হলেন। বর্গাকার বিন্যাসের ফরাসি পদাতিক অশ্বারোহী আক্রমণ ভাঙলো; মামলুক বাহিনী ছত্রভঙ্গ হলো এবং কায়রো দুই দিন পর প্রতিরোধ ছাড়াই আত্মসমর্পণ করলো। মুরাদ বে উচ্চ মিশরে, ইব্রাহিম বে সিরিয়ায় সরে গেলেন। ফরাসিরা কায়রোতে দিওয়ান গঠন করে উলেমার হাত দিয়ে প্রশাসন চালানোর চেষ্টা করলো; 1798 সালের অক্টোবরে ও 1800 সালের মার্চে দুটি বড় কায়রো বিদ্রোহ ঘটলো।", "ad9a3113"]},
"OLAYLAR_EK9:1799-03-18:0":{"b": ["নেপোলিয়নের আক্কা অবরোধ — সিরিয়া অভিযান থামানো", "d2a947ad"], "d": ["অটোমানদের মিশর ফিরিয়ে নিতে প্রস্তুত করা বাহিনী ছত্রভঙ্গ করতে চাওয়া নেপোলিয়ন 1799 সালের শুরুতে সিরিয়ায় অগ্রসর হলেন; আরিশ 18 ফেব্রুয়ারি, জাফা মার্চে দখল করলেন এবং 18 মার্চ 1799 তারিখে আক্কা অবরোধ করলেন। জাজ্জার আহমেদ পাশার প্রতিরক্ষা ও ব্রিটিশ অ্যাডমিরাল সিডনি স্মিথের সমুদ্র থেকে সহায়তা অবরোধকে দুই মাস ভাঙলো; অবরোধ কামান সমুদ্রে দখল হওয়ায় প্রাচীর পেরোনো যায়নি। নেপোলিয়ন মে মাসে সরে গেলেন এবং এই পরাজয় ফরাসি দখলের সর্বোচ্চ সীমা হলো।", "288b9bd9"]},
"OLAYLAR_EK9:1832-11-22:0":{"b": ["আমির আবদুল কাদিরের রাষ্ট্র প্রতিষ্ঠা — পশ্চিম আলজেরিয়ায় প্রতিরোধের কেন্দ্রীকরণ", "9e482383"], "d": ["আলজিয়ার্সের পতনের পর ছত্রভঙ্গ প্রতিরোধ কাদিরি শায়খ মুহিউদ্দিনের পুত্র তরুণ আবদুল কাদিরকে ঘিরে জড়ো হলো; 22 নভেম্বর 1832 তারিখে মুয়াসকারের কাছে গোত্রপ্রধানরা তাঁকে 'আমিরুল মুমিনিন' উপাধিতে বায়াত করলেন। তাঁর গড়া কাঠামো গোত্রীয় মিত্রতা নয়, নিয়মিত রাষ্ট্র ছিল: টাকশাল, বারুদ কারখানা, কর ব্যবস্থা ও তাগদেমতে একটি রাজধানী ছিল। ফ্রান্স 1837 সালের তাফনা চুক্তিতে তাঁর আধিপত্য আনুষ্ঠানিকভাবে স্বীকার করলো। আবদুল কাদির অটোমানদের নয়, মরক্কোর সুলতান আবদুর রহমানের আধিপত্যে আশ্রয় নিলেন; অর্থাৎ এই ভূখণ্ড 1832 সালের পর অটোমান আনুগত্যে নয়। 23 ডিসেম্বর 1847 তারিখে আত্মসমর্পণ করলেন এবং অটোমান রাষ্ট্রও একই বছর আলজেরিয়ার ওপর নিজের অধিকার শেষ বলে ঘোষণা করলো।", "ee2bb181"]},
"OLAYLAR_EK9:1837-10-13:0":{"b": ["কনস্তান্তিনের পতন — পূর্ব আলজেরীয় বেইলিকের অবসান", "159fed36"], "d": ["1830 সালে আলজিয়ার্সের পতনের পর পূর্ব বেইলারবেইত্ব ভাঙেনি: শেষ বে আহমেদ কনস্তান্তিনে নিজের শাসন চালিয়ে গেলেন এবং অটোমানদের নামে কাজ করছেন বলে ঘোষণা করলেন। ফরাসিদের 1836 সালের প্রথম অভিযান বিপর্যয়ে শেষ হলো; দ্বিতীয় অভিযান 6 অক্টোবর 1837 তারিখে শহর অবরোধ করলো, সেনাপতি দাম্রেমঁ 12 অক্টোবর গোলার আঘাতে নিহত হলেন এবং 13 অক্টোবর প্রাচীর পেরিয়ে শহর রাস্তায় রাস্তায় লড়াই করে দখল হলো। আহমেদ বে পর্বতে সরে গেলেন এবং কেবল 1848 সালে আত্মসমর্পণ করলেন। এই তারিখ আলজেরিয়ার পূর্বে তিনশ বছরের অটোমান-তুর্কি শাসনের কার্যত সমাপ্তি।", "41606785"]},
"OLAYLAR_EK9:1840-01-01:0":{"b": ["তাকা অঞ্চল জয় ও কাসালা প্রতিষ্ঠা", "cc3e0631"], "d": ["সুদানের শাসক আহমেদ পাশা আবু ভিদান 1840 সালে আতবারা ও গাশ নদীর মধ্যবর্তী তাকা অঞ্চল মিশরীয় শাসনে যুক্ত করলেন এবং কাসালা শহর সামরিক ঘাঁটি হিসেবে স্থাপন করলেন। শহর সেন্নার ও সুয়াকিনের মধ্যকার কাফেলা পথ এবং হাবেশ সীমান্ত বলয় নিয়ন্ত্রণকারী মুদিরিয়াতের কেন্দ্র হলো।", "b7898c36"]},
"OLAYLAR_EK9:1841-01-01:0":{"b": ["মুয়াসকারের (মাসকারা) ফরাসি দখল — আবদুল কাদিরের রাজধানী হারানো", "bd363c05"], "d": ["বুজোর 1841 সালে গভর্নর হয়ে আসার সঙ্গে ফরাসি কৌশল বদলালো: উপকূলে টিকে থাকার বদলে অভ্যন্তরের শহরগুলো একে একে দখল করা। ওরান, মোস্তাগানেম ও মেদেয়া থেকে বেরোনো চলমান বাহিনী আবদুল কাদিরের নিয়মিত রাষ্ট্রের কেন্দ্রগুলো নিল; টাকশাল, বারুদ কারখানা ও শস্যগুদামসহ প্রকৃত রাজধানী মুয়াসকার ছিল এগুলোর মধ্যে সবচেয়ে গুরুত্বপূর্ণ। আমির এরপর স্থির কেন্দ্র গড়া ছেড়ে দিয়ে সেনাবাহিনীকে 'স্মালা' নামের যাযাবর শিবিরে রূপ দিলেন।", "b5e65ffc"]},
"OLAYLAR_EK9:1843-01-01:0":{"b": ["শেলিফ উপত্যকা ও তেনেসের দখল — অরলিয়ানসভিল প্রতিষ্ঠা", "e1eeeb68"], "d": ["আবদুল কাদিরকে অনুসরণ করতে ফরাসিরা 1843 সালের এপ্রিলে শেলিফ উপত্যকার মাঝখানে অরলিয়ানসভিল নামের নতুন শহর প্রতিষ্ঠা করলো; একই বছর উপকূলের তেনেস বন্দরও দখল হলো। এভাবে আলজিয়ার্স ও ওরানের মধ্যবর্তী অভ্যন্তরীণ করিডর ফরাসি নিয়ন্ত্রণে এলো এবং দাহরা পর্বতের প্রতিরোধ ঘেরাও হলো। একই বছরের 16 মে আবদুল কাদিরের যাযাবর শিবির 'স্মালা' দৈবক্রমে খুঁজে পাওয়া গিয়ে ছত্রভঙ্গ করা হলো।", "67e95822"]},
"OLAYLAR_EK9:1843-06-12:0":{"b": ["সিদি বেল আব্বেস সুরক্ষিত শিবির স্থাপন", "fb33ec29"], "d": ["বুজো 12 জুন 1843 তারিখে জেনারেল বেদোকে সিদি বেল আব্বেসে পরিখা ও প্রাচীরসহ সুরক্ষিত শিবির গড়ার আদেশ দিলেন; নির্মাণ 18 জুনে শুরু হলো এবং একই বছরের নভেম্বরে বিদেশি বাহিনীর একটি ব্যাটালিয়ন এখানে বসলো। শিবির ওরান ও তিলিমসানের মধ্যবর্তী অভ্যন্তরীণ সমভূমি নিয়ন্ত্রণকারী স্থায়ী ঘাঁটি হলো।", "aab075d5"]},
"OLAYLAR_EK9:1844-01-01:0":{"b": ["নেদরোমা ও মরক্কো সীমান্ত বলয়ের ফরাসি নিয়ন্ত্রণে যাওয়া", "61d821f3"], "d": ["আবদুল কাদিরের 1843 সালে মরক্কোয় সরে যাওয়ার পর তিলিমসানের উত্তর-পশ্চিমের নেদরোমা ও ত্রারা উপকূল ফরাসি নিয়ন্ত্রণে এলো। 14 আগস্ট 1844 ইসলি যুদ্ধ মরক্কোর সেনাবাহিনীকে ছত্রভঙ্গ করলো এবং দুই দেশের মধ্যকার সীমানা 18 মার্চ 1845 লাল্লা মাগনিয়া চুক্তিতে টানা হলো; নেদরোমা এই রেখার আলজেরীয় দিকে থাকলো।", "0456a776"]},
"OLAYLAR_EK9:1852-12-04:0":{"b": ["আগুয়াতের (লাঘোয়াত) পতন — সাহারার দরজা খুলে যাওয়া", "b161b32c"], "d": ["জেনারেল পেলিসিয়ে ছয় হাজার লোকের বাহিনী নিয়ে 21 নভেম্বর 1852 তারিখে আগুয়াত অবরোধ করলেন এবং 4 ডিসেম্বর শহর রক্তাক্ত আক্রমণে পতিত হলো। আগুয়াত তেল ও সাহারার মধ্যবর্তী পথ রক্ষাকারী মরূদ্যান শহর ছিল; এর পতন ফরাসি অগ্রগতি মরুভূমির কাফেলা পথে খুলে দিল এবং মিজাব কনফেডারেশনের এক বছরের মধ্যে করের আওতায় আসার পথ প্রস্তুত করলো।", "049b3d0a"]},
"OLAYLAR_EK9:1872-01-01:0":{"b": ["বোগোস (কেরেন) অঞ্চলের মিশরে অন্তর্ভুক্তি", "b2ab83ce"], "d": ["খেদিভ ইসমাইলের লোহিত সাগরের পশ্চিম উপকূলে গড়া 'পূর্ব সুদান ও লোহিত সাগর উপকূল' প্রদেশের গভর্নর ভের্নার মুনজিঙ্গার পাশা 1872 সালে বিলেন জনগোষ্ঠীর বসবাসের বোগোস অঞ্চল ও কেন্দ্র কেরেন মিশরের সঙ্গে যুক্ত করলেন। এটি মিশরের হাবেশ মালভূমির কিনারায় সবচেয়ে স্থায়ী অগ্রগতি ছিল এবং হাবেশের সঙ্গে বারো বছর স্থায়ী সীমান্ত বিরোধ শুরু করলো।", "e52afaf4"]},
"OLAYLAR_EK9:1874-11-02:0":{"b": ["দারফুর সালতানাতের মিশরে অন্তর্ভুক্তি — জুবাইর পাশা এল-ফাশিরে প্রবেশ করলেন", "f41268ed"], "d": ["হাতির দাঁত ও দাস বাণিজ্যে শক্তিশালী জুবাইর রহমত পাশা রেমিংটন রাইফেলে সজ্জিত বাহিনী নিয়ে 25 অক্টোবর 1874 তারিখে মেনেভাশিতে ফুর সেনাবাহিনীকে ছত্রভঙ্গ করলেন; সুলতান ইব্রাহিম যুদ্ধে নিহত হলেন। জুবাইর 2 নভেম্বর এল-ফাশিরে যুদ্ধ ছাড়াই প্রবেশ করলেন এবং 1603 সাল থেকে চলে আসা কেইরা রাজবংশের শাসন কার্যত শেষ হলো। দারফুর এভাবে কাভালালি মিশরের সুদান প্রদেশগুলোতে যুক্ত হলো; কিন্তু কেইরা পরিবারের পর্বতে প্রতিরোধ 1891 সাল পর্যন্ত চললো।", "b9679678"]},
"OLAYLAR_EK9:1882-01-01:0":{"b": ["মিজাব মরূদ্যানগুলোর (গারদাইয়া) অন্তর্ভুক্তি", "9372959f"], "d": ["মিজাবের ইবাদি শহরগুলো 1852 সালে ফ্রান্সকে কর দিতে সম্মত হলেও অভ্যন্তরীণ প্রশাসন রক্ষা করেছিল; ত্রিশ বছর পর, 1882 সালে অঞ্চল সরাসরি ফরাসি ভূখণ্ডে যুক্ত হলো এবং গারদাইয়া সামরিক প্রশাসনের অধীন হলো। এভাবে উত্তর সাহারার শেষ স্বায়ত্তশাসিত বলয়ও আইনত শেষ হলো।", "8ced1a9f"]},
"OLAYLAR_EK9:1882-07-11:0":{"b": ["আলেকজান্দ্রিয়ার বোমাবর্ষণ ও ব্রিটিশ অবতরণ", "18d57bf8"], "d": ["উরাবি পাশার নেতৃত্বাধীন অফিসার আন্দোলন খেদিভকে নিয়ন্ত্রণে নিলে ব্রিটেন সুয়েজ পথের নিরাপত্তার অজুহাতে হস্তক্ষেপ করলো। অ্যাডমিরাল সেমুরের বহর 11-12 জুলাই 1882 তারিখে আলেকজান্দ্রিয়ার উপকূলীয় দুর্গে বোমাবর্ষণ করলো; শহরে লাগা আগুন ও লুটপাটের পর 15 জুলাই ব্রিটিশ বাহিনী স্থলে নামলো। অটোমান রাষ্ট্র আইনত অধিপতি থাকা প্রদেশে এই অভিযান আটকাতে পারলো না এবং হস্তক্ষেপে যোগ দেওয়ার আহ্বানও উত্তরহীন রাখলো। এভাবে বত্রিশ বছর স্থায়ী দখলের প্রথম পদক্ষেপ নেওয়া হলো।", "d828a872"]},
"OLAYLAR_EK9:1882-09-13:0":{"b": ["তেল এল-কেবিরের যুদ্ধ — উরাবির সেনাবাহিনীর ছত্রভঙ্গ", "8e38fecf"], "d": ["উলসলি বাহিনী সুয়েজ খাল হয়ে ইসমাইলিয়ায় নামিয়ে মরুভূমি ধরে হেঁটে 13 সেপ্টেম্বর 1882 তারিখের ভোরে তেল এল-কেবিরের মিশরীয় পরিখায় অতর্কিত হামলা চালালেন; যুদ্ধ এক ঘণ্টায় শেষ হলো। উরাবি পরদিন আত্মসমর্পণ করলেন এবং ব্রিটিশ অশ্বারোহী একই দিনে কায়রোতে প্রবেশ করলো। এই তারিখের পর মিশরের আর্থিক, সামরিক ও পররাষ্ট্র বিষয় কার্যত ব্রিটিশ নিয়ন্ত্রণে গেল; অটোমান আধিপত্য আইনত 1914 সাল পর্যন্ত চললো।", "a399d51c"]},
"OLAYLAR_EK9:1883-06-08:0":{"b": ["মার্সা (লা মার্সা) কনভেনশন — তিউনিসীয় আশ্রয়ের সম্পূর্ণতা", "71338640"], "d": ["12 মে 1881 তারিখের বার্দো (কাসর-ই সাইদ) চুক্তি তিউনিসের পররাষ্ট্র বিষয় ফ্রান্সকে ছেড়ে দিলেও অভ্যন্তরীণ শাসন বের হাতে রেখেছিল; দুই বছর পর 8 জুন 1883 তারিখে স্বাক্ষরিত মার্সা কনভেনশন আর্থিক ও প্রশাসনিক সংস্কারও ফরাসি নিয়ন্ত্রণে দিল এবং আশ্রয় সম্পূর্ণ করলো। অটোমান রাষ্ট্র তিউনিসের ওপর আধিপত্য দাবি চালিয়ে গেল এবং দখল কখনো স্বীকার করলো না, কিন্তু কার্যত কোনো পাল্টা পদক্ষেপ নিতে পারলো না। এভাবে 1574 সাল থেকে অটোমান ওজাক তিউনিস আনুষ্ঠানিকভাবে ফরাসি আশ্রয়ে এলো।", "c04210c4"]},
"OLAYLAR_EK9:1883-11-05:0":{"b": ["শেইকান বিপর্যয় — হিকস পাশার বাহিনীর ধ্বংস", "a0e08986"], "d": ["কায়রো থেকে পাঠানো প্রায় দশ হাজার লোকের মিশরীয় বাহিনীর অধিনায়কত্বকারী অবসরপ্রাপ্ত ব্রিটিশ কর্মকর্তা হিকস পাশা কর্দোফান মরুভূমিতে পানি ও পথপ্রদর্শক ছাড়া এগোনোর সময় 5 নভেম্বর 1883 তারিখে শেইকানে মাহদি বাহিনীর অবরোধে পড়লেন এবং বাহিনী প্রায় সম্পূর্ণ ধ্বংস হলো। এই বিপর্যয় সুদানে মিশরীয় শাসনের মেরুদণ্ড ভাঙলো: এক মাসের মধ্যে দারফুর ও বাহর এল-গাজাল আত্মসমর্পণ করলো, কর্দোফান পুরোটাই মাহদির হাতে গেল। খার্তুমের পতনের পথ এখান থেকে শুরু।", "c78a6d57"]},
"OLAYLAR_EK9:1883-12-23:0":{"b": ["দারফুরের মাহদি বাহিনীর হাতে যাওয়া — স্লাটিন পাশার আত্মসমর্পণ", "6d8992d4"], "d": ["দারফুরের জেনারেল গভর্নর স্লাটিন পাশা 1882 সাল থেকে রিজেইকাত গোত্রের মাহদিবাদী বিদ্রোহের সঙ্গে লড়ছিলেন; সৈন্যদের পরাজয় তাঁর খ্রিস্টান হওয়ার ঘাড়ে চাপানো হচ্ছে ভেবে 1883 সালে প্রকাশ্যে মুসলিম হলেন এবং আবদুল কাদির নাম নিলেন। হিকস পাশার বাহিনী 1883 সালের নভেম্বরে কর্দোফানে ধ্বংস হওয়ার পর প্রতিরোধের অর্থ থাকলো না এবং 23 ডিসেম্বর 1883 তারিখে আমির মাদিব্বোর কাছে আত্মসমর্পণ করলেন। দারফুরের ছোট মিশরীয় ঘাঁটিগুলোও অল্প সময়ে একই পথ ধরলো; দশ বছরের তুর্কি-মিশরীয় শাসন শেষ হলো। এই ঘটনার ফলে জেবেল মাররা (দারফুর) মাহদি রাষ্ট্রের শাসনে গেল।", "bd700253"]},
"OLAYLAR_EK9:1884-01-01:0":{"b": ["জেইলা ও সোমালি উপকূলের ব্রিটিশ শাসনে যাওয়া", "1d649502"], "d": ["মাহদি বিদ্রোহ মিশরের সুদান ও লোহিত সাগর গ্যারিসন ধসিয়ে দিলে কায়রো হাবেশ উপকূলের দূরবর্তী ঘাঁটিগুলো খালি করতে বাধ্য হলো। এডেনের ব্রিটিশ প্রশাসন 1884 সালে জেইলা ও বেরবেরায় সেনা নামালো; পরের বছর সোমালি গোত্রপ্রধানদের সঙ্গে আশ্রয় চুক্তি স্বাক্ষর করে ব্রিটিশ সোমালিল্যান্ড গঠিত হলো। 1559 সাল থেকে হাবেশ প্রদেশের অধীন জেইলা এভাবে হাতছাড়া হলো।", "3c41ddf4"]},
"OLAYLAR_EK9:1884-01-15:0":{"b": ["ফাশির গ্যারিসনের মাহদিবাদীদের কাছে আত্মসমর্পণ", "68f0760d"], "d": ["স্লাটিনের 23 ডিসেম্বর 1883 তারিখের আত্মসমর্পণের পরও ফাশির দুর্গের মিশরীয় গ্যারিসন প্রতিরোধ করলো। সাত দিনের অবরোধে কূপ হারানো গ্যারিসন 15 জানুয়ারি 1884 তারিখে আত্মসমর্পণ করলো; অস্ত্র ফেলে দুর্গ মাহদিবাদীদের হাতে গেল।", "18287ab0"]},
"OLAYLAR_EK9:1884-06-03:0":{"b": ["হিউয়েট (আদোয়া) চুক্তি — বোগোস হাবেশকে ছেড়ে দেওয়া", "0de1b701"], "d": ["মাহদি বিদ্রোহ সুদানের মিশরীয় গ্যারিসনগুলো ঘেরাও করলে ব্রিটেন হাবেশের সাহায্য পেতে 3 জুন 1884 তারিখে আদোয়ায় চতুর্থ ইয়োহান্নেসের সঙ্গে চুক্তি স্বাক্ষর করলো। চুক্তির দ্বিতীয় ধারা বোগোসকে হাবেশের কাছে ফেরত দিচ্ছিল, বিনিময়ে হাবেশ অবরুদ্ধ গ্যারিসনগুলোর মাসাওয়া হয়ে উদ্ধারের সুযোগ দিচ্ছিল। কেরেন এভাবে বারো বছরের মিশরীয় শাসন থেকে বেরিয়ে গেল; পাঁচ বছর পর অঞ্চল ইতালীয় ইরিত্রিয়ায় যুক্ত হবে।", "b7e73617"]},
"OLAYLAR_EK9:1896-09-23:0":{"b": ["দোঙ্গোলা পুনরুদ্ধার — নীল বরাবর অভিযানের শুরু", "f63aa14f"], "d": ["ইতালীয়দের আদোয়ায় পরাজয়ের পর ব্রিটেন কিচেনারের নেতৃত্বে মিশরীয় বাহিনীকে নীল বরাবর দক্ষিণে এগিয়ে নিল। রেলপথ মরুভূমিতে এগোনোর সঙ্গে সঙ্গে সরবরাহ সমস্যার সমাধান হলো এবং দোঙ্গোলা প্রদেশ 23 সেপ্টেম্বর 1896 তারিখে পুনরুদ্ধার হলো। এগারো বছরের মাহদি শাসন এখানে শেষ হলো; অভিযান আরও দুই বছর চলে ওমদুরমানে পৌঁছাবে।", "ef465d34"]},
"OLAYLAR_EK9:1898-09-02:0":{"b": ["ওমদুরমানের যুদ্ধ — মাহদি রাষ্ট্রের পতন", "28dff7b2"], "d": ["কিচেনারের কামান ও মেশিনগানে সজ্জিত ব্রিটিশ-মিশরীয় বাহিনী 2 সেপ্টেম্বর 1898 তারিখে ওমদুরমানের সামনে খলিফা আবদুল্লাহ আত-তাআইশির বাহিনীকে কয়েক ঘণ্টায় ছত্রভঙ্গ করলো। পরদিন খার্তুমে প্রবেশ করা হলো এবং তেরো বছর আগে গর্ডন নিহত হওয়া প্রাসাদে পতাকা তোলা হলো। মাহদি রাষ্ট্রের রাজধানী পতিত হলো; খলিফা 1899 সালের শেষে অনুসরণ অভিযানে নিহত হলেন। প্রকৃত আধিপত্য এই তারিখে হাতবদল হয় — 19 জানুয়ারি 1899 অবশ্য প্রশাসনের আইনি কাঠামো গড়া চুক্তি। মাহদি রাষ্ট্রের এই পরাজয়ে দারফুর (এল-ফাশির, নিয়ালা, জেনেইনা, কুতুম প্রভৃতি) আলী দিনারের পুনঃপ্রতিষ্ঠিত দারফুর সালতানাতের হাতে গেল।", "ad27827a"]},
"OLAYLAR_EK9:1899-01-19:0":{"b": ["কন্ডোমিনিয়াম চুক্তি — সুদানের ব্রিটিশ-মিশরীয় যৌথ শাসন", "8033c688"], "d": ["ওমদুরমানের চার মাস পর কায়রোতে স্বাক্ষরিত চুক্তি সুদানকে 'অ্যাংলো-মিশরীয় সুদান' নামে দুই রাষ্ট্রের যৌথ শাসনে বাঁধলো: দুটি পতাকা একসঙ্গে ওঠানো হবে, গভর্নর জেনারেল খেদিভ কর্তৃক ব্রিটেনের সম্মতিতে নিযুক্ত হবেন। বাস্তবে প্রশাসন সম্পূর্ণ ইংরেজদের হাতে ছিল। অটোমান রাষ্ট্র সুদানের ওপর তাদের অধিকার মিশরের মাধ্যমে নিজেদের বলে দাবি করে চুক্তিতে পক্ষ হলো না এবং স্বীকার করলো না; কিন্তু কার্যত বাইরে থাকলো। এই চুক্তির মাধ্যমে 22তম সমান্তরালের দক্ষিণের সুদান ভূখণ্ড (দোঙ্গোলা, খার্তুম, সেন্নার, কর্দোফান, সুয়াকিন উপকূল প্রভৃতি) ব্রিটিশ-মিশরীয় যৌথ শাসনে (ব্রিটিশ-মিশরীয় সুদান) গেল।", "097331bb"]},
"OLAYLAR_EK9:1911-10-08:0":{"b": ["তোবরুকে ইতালীয় অবতরণ — ত্রিপোলিতানিয়ায় প্রথম দখল", "44780018"], "d": ["ইতালি 29 সেপ্টেম্বর 1911 তারিখে যুদ্ধ ঘোষণা করলো এবং তার নৌবহর 25-26 সেপ্টেম্বর উপকূল অবরোধ করলো। প্রথম স্থল অভিযান 8 অক্টোবর তোবরুকে হলো: ছোট অটোমান গ্যারিসন অভ্যন্তরে সরে গেল এবং বন্দর যুদ্ধ ছাড়াই দখল হলো। তোবরুক মিশর সীমান্তের সবচেয়ে কাছের অটোমান বন্দর ছিল; এর পতন বারকার পূর্ব পাশ খুলে দিল এবং ইতালীয় বাহিনীর উপকূল ধরে পশ্চিমে অগ্রসর হওয়া সহজ করলো।", "fa489107"]},
"OLAYLAR_EK9:1911-10-09:0":{"b": ["ত্রিপোলি শহরের ইতালীয়দের কাছে আত্মসমর্পণ", "785091ad"], "d": ["ত্রিপোলি তিন দিনের বোমাবর্ষণের পর 9 অক্টোবর 1911 তারিখে আত্মসমর্পণ করলো। অটোমান বাহিনী শহর রক্ষার বদলে আজিজিয়া ও গারইয়ানে সরে গিয়ে অভ্যন্তরে প্রতিরোধ সংগঠিত করা বেছে নিল; এনভার ও মুস্তাফা কেমাল বেদের যোগ দেওয়া এই প্রতিরোধ যুদ্ধের শেষ পর্যন্ত ইতালীয়দের উপকূলীয় ফালিতে আটকে রাখলো। অর্থাৎ শহর পতিত হলেও প্রদেশের অভ্যন্তর অটোমান নিয়ন্ত্রণে থাকলো।", "7deeaf70"]},
"OLAYLAR_EK9:1911-10-16:0":{"b": ["দের্নার ইতালীয় অবতরণে হাতছাড়া হওয়া", "f014c741"], "d": ["তোবরুকের পর বারকার দ্বিতীয় বন্দর দের্নার পালা এলো; শহর 16 অক্টোবর 1911 তারিখে দখল হলো। দের্নার আশেপাশের মালভূমি সেনুসিয়া তরিকার সবচেয়ে ঘন অঞ্চল ছিল এবং শায়খ আহমেদ শরিফের জিহাদ আহ্বানে জড়ো হওয়া মুজাহিদরা ইতালীয়দের বন্দরের আশেপাশে অবরুদ্ধ রাখলো। দখল শহরে সীমিত থাকলো, পশ্চাদভূমিতে কখনো ছড়াতে পারলো না।", "b6ada646"]},
"OLAYLAR_EK9:1911-10-21:0":{"b": ["বেনগাজিতে ইতালীয় অবতরণ — বারকা সানজাকের কেন্দ্র হারানো", "f9183c40"], "d": ["বারকার কেন্দ্র বেনগাজি 21 অক্টোবর 1911 তারিখে উপকূলের চতুর্থ ও সবচেয়ে গুরুত্বপূর্ণ অবতরণে দখল হলো। এভাবে ইতালি যুদ্ধ ঘোষণার তিন সপ্তাহ পর ত্রিপোলিতানিয়া প্রদেশের সব বড় বন্দর (ত্রিপোলি, তোবরুক, দের্না, বেনগাজি) হাতে রাখলো; কিন্তু কোনোটির পশ্চাদভূমিতে ঢুকতে পারলো না। যুদ্ধের অবশিষ্ট এক বছর উপকূলের এই চার বিন্দু থেকে অভ্যন্তরের দিকে নিষ্ফল হামলায় কাটলো।", "6181e67f"]},
"OLAYLAR_EK9:1911-11-05:0":{"b": ["ইতালির একতরফা অন্তর্ভুক্তি ডিক্রি", "cfe3f9c2"], "d": ["ইতালি যুদ্ধ চলাকালে 5 নভেম্বর 1911 তারিখে এক ডিক্রি জারি করে ত্রিপোলিতানিয়া ও বারকা অন্তর্ভুক্ত করেছে বলে ঘোষণা করলো। অটোমান রাষ্ট্র এটি স্বীকার করলো না এবং যুদ্ধ আরও এক বছর চললো; অন্তর্ভুক্তি কেবল 18 অক্টোবর 1912 উশি চুক্তিতে আইনি বৈধতা পেল। ডিক্রি তাই মানচিত্রে অটোমান রং বদলায় না — আইনি মালিকানা 1912 সাল পর্যন্ত অটোমানদের, ইতালীয় নিয়ন্ত্রণ ডোরাকাটা দখল হিসেবে দেখানো হয়।", "23668758"]},
"OLAYLAR_EK:1300-01-01:0":{"b": ["কোপ্রুহিসারের দখল ও ইয়েনিশেহির প্রতিষ্ঠার প্রস্তুতি", "39abff03"], "d": ["বুরসা ও ইজনিকের মধ্যবর্তী গিরিপথ দুর্গগুলো দখল করে দুই শহরকে অবরোধে রাখার অগ্রবর্তী সদর দপ্তরের ভিত্তি স্থাপিত হলো।", "72fa9808"]},
"OLAYLAR_EK:1301-01-01:0":{"b": ["ইয়েনিশেহিরের প্রতিষ্ঠা", "d3275837"], "d": ["বুরসা ও ইজনিক অবরোধ পরিচালনার জন্য প্রথম নিয়মিত অটোমান গ্যারিসন-বসতি স্থাপিত হলো; ওরহান গাজি এখানে জন্মগ্রহণ করেন।", "39c98a4b"]},
"OLAYLAR_EK:1302-08-01:0":{"b": ["ইজনিকের প্রথম অবরোধ ও Marmaracık-এর বিজয়", "cdca2349"], "d": ["ইজনিক প্রথমবার অবরুদ্ধ হলো কিন্তু দখল হয়নি (চূড়ান্ত বিজয় 1331); কাছের Marmaracık দুর্গ এ সময় দখল হলো।", "31c4c65f"]},
"OLAYLAR_EK:1305-06-01:0":{"b": ["কাতালান বাহিনীর আনাতোলিয়া অভিযান", "4fd940d5"], "d": ["বাইজেন্টাইনরা তুর্কি অগ্রযাত্রা ঠেকাতে ভাড়া করা কাতালান দল সাময়িক সাফল্য পেলেও স্থায়ী হতে পারেনি; তাদের সরে যাওয়ায় সীমান্ত বেগলিকগুলোর অগ্রযাত্রা দ্রুত হলো।", "89381e71"]},
"OLAYLAR_EK:1313-01-01:0":{"b": ["কোসে মিহালের মুসলিম হয়ে অটোমানদের সঙ্গে যোগদান", "ca0d86e1"], "d": ["হারমানকায়া টেকফুর কোসে মিহাল তাঁর দুর্গ ও লোকজনসহ মুসলিম হয়ে ওসমান গাজির সঙ্গে যোগ দিলেন; প্রথম বাইজেন্টাইন বংশোদ্ভূত অটোমান সেনাপতি হলেন।", "327b4cdc"]},
"OLAYLAR_EK:1320-01-01:0":{"b": ["ওরহান বেগের কার্যত শাসন গ্রহণ", "6dadbefc"], "d": ["ওসমান গাজির বার্ধক্য ও অসুস্থতার কারণে বুরসা অবরোধ ও অভিযানের কার্যত পরিচালনা পুত্র ওরহান বেগের হাতে গেল (সিংহাসনে আনুষ্ঠানিক আরোহণ 1326 সালে)।", "280c6e0d"]},
"OLAYLAR_EK:1321-04-01:0":{"b": ["মুদানিয়ার দখল", "0a623368"], "d": ["বুরসার বন্দর মুদানিয়া দখল করে শহরের সমুদ্রসংযোগ কেটে দেওয়া হলো; বুরসা অবরোধ শ্বাসরোধের পর্যায়ে ঢুকল।", "c13020d5"]},
"OLAYLAR_EK:1324-01-01:0":{"b": ["আকইয়াজি ও ইমরালি দ্বীপের বিজয়", "d041b0c8"], "d": ["সাকারিয়ার উত্তরের আকইয়াজি দখল হলো; ইমরালি দ্বীপ দখলে অটোমানরা প্রথমবার মারমারা দ্বীপের প্রতিবেশী হলো।", "591424a4"]},
"OLAYLAR_EK:1324-03-01:0":{"b": ["জেমলিক (Kios) ও আরমুতলুর বিজয়", "682d3bac"], "d": ["বুরসার শেষ সমুদ্রসংযোগও কেটে দেওয়া হলো এবং শহরকে 1326 সালের আত্মসমর্পণের জন্য প্রস্তুত করা হলো।", "c2b80b4a"]},
"OLAYLAR_EK:1326-01-01:0":{"b": ["আকচা কোজা কান্দিরা ও আশপাশ দখল করলেন", "341bb97e"], "d": ["ওরহান গাজির সীমান্ত বেগদের একজন আকচা কোজা সাপাঞ্জা হ্রদের পশ্চিমের ঘাঁটি থেকে ইজমিত অঞ্চলে হানা দিতে দিতে 1326-এর কাছাকাছি কান্দিরা ও আশপাশ দখল করলেন। ইজমিত তখনও বাইজেন্টাইন হাতে ছিল; শহর কেবল 1337 সালে পতিত হবে।", "ed042ad1"]},
"OLAYLAR_EK:1326-01-01:1":{"b": ["ইয়ালোভা ও কারামুরসেলের অন্তর্ভুক্তি", "133cb07a"], "d": ["ইজমিত উপসাগরের দক্ষিণ তীরের ইয়ালোভা ও আশপাশ এ বছর তুর্কিদের হাতে এলো; উপকূলরেখা ওরহান বে তিমার হিসেবে কারামুরসেল গাজিকে দিলেন।", "592a86bc"]},
"OLAYLAR_EK:1328-01-01:0":{"b": ["আকচা কোজা আয়দোস ও সামান্দিরা দুর্গ নিলেন", "ce4daa8a"], "d": ["কান্দিরা দখলের পর আকচা কোজা কোনুরাল্প ও গাজি আবদুররহমানের সঙ্গে কার্তাল অঞ্চলের আয়দোস দুর্গ, পরে তার উত্তরের সামান্দিরা দুর্গ দখল করলেন; সামান্দিরা অঞ্চল তাঁকে সম্পত্তি হিসেবে দেওয়া হলো। আকচা কোজা 1328 সালে কান্দিরার কাছে মারা গেলেন; সীমান্ত বেগলিক অঞ্চল শাহজাদা মুরাদকে দেওয়া হলো।", "f2ef1bde"]},
"OLAYLAR_EK:1330-01-01:0":{"b": ["অটোমান-আইদিন-সারুহান মৈত্রী", "9df6bb74"], "d": ["বাইজেন্টাইনদের বিরুদ্ধে তিন বেগলিক যৌথভাবে কাজ করল; আইদিনোগলু উমুর বেগের নৌবহর থ্রেস উপকূলে হানা দিয়ে বাইজেন্টাইনদের দ্বিতীয় ফ্রন্টে ক্লান্ত করল।", "32ca49ea"]},
"OLAYLAR_EK:1346-06-01:0":{"b": ["ওরহান গাজি – থিওডোরা বিবাহ: বাইজেন্টাইন মৈত্রী", "9b67a590"], "d": ["বাইজেন্টাইন সিংহাসন-সংগ্রামে কান্তাকুজেনোসকে সমর্থনকারী ওরহান গাজি তাঁর কন্যা থিওডোরাকে বিয়ে করলেন; এই মৈত্রী অটোমান বাহিনীকে রুমেলিকে নিবিড়ভাবে চেনার সুযোগ দিল।", "4f8f52d9"]},
"OLAYLAR_EK:1354-08-01:0":{"b": ["আঙ্কারা দখল", "49bf1f6d"], "d": ["আখি শাসনাধীন আঙ্কারা অটোমান প্রশাসনে এলো; মধ্য আনাতোলিয়ার পথ খুলল। একই তারিখে অন্তর্ভুক্ত অন্যান্য স্থান: সিভরিহিসার, চানকিরি।", "eec5d13e"]},
"OLAYLAR_EK:1357-01-01:0":{"b": ["সুলেইমান পাশার আমলে থ্রেসে অগ্রযাত্রা: মালকারা, ইপসালা ও তেকিরদাগ", "fb31cf02"], "d": ["গালিপোলিতে সেতুমুখ গড়ার পর সুলেইমান পাশা উপদ্বীপ থেকে উত্তরে বেরিয়ে মারমারা উপকূল ও মারিৎসা মোহনার মধ্যবর্তী সমভূমি ধাপে ধাপে দখল করলেন। মালকারা, ইপসালা ও রোদোস্তো (তেকিরদাগ) এভাবে গালিপোলি ও মারিৎসা উপত্যকাকে যুক্ত করা একটি অবিচ্ছিন্ন করিডর গড়ল। এই করিডর ছাড়া এডির্নের দিকে এগোনো যেত না; শাহজাদার 1357 সালের আকস্মিক মৃত্যুতে থেমে যাওয়া অগ্রযাত্রা লালা শাহিন ও হাজি ইলবে চালিয়ে যাবেন।", "721cac95"]},
"OLAYLAR_EK:1357-08-01:0":{"b": ["শাহজাদা খলিলের অপহরণ", "b52ac3d7"], "d": ["ওরহান গাজির ছোট ছেলে খলিল ফোচার জলদস্যুদের হাতে অপহৃত হলেন; মুক্তিপণ সংকট বছরের পর বছর অটোমান-বাইজেন্টাইন সম্পর্ককে ব্যস্ত রাখল।", "812e3cb6"]},
"OLAYLAR_EK:1360-01-01:0":{"b": ["এডির্নের সাহায্য পথ কাটা: চোরলু, লুলেবুরগাজ, বাবাএস্কি ও কেশান দুর্গ", "8e8ad485"], "d": ["হালিলের উদ্ধারের পর বিজয় অভিযান আবার শুরু করা শাহজাদা মুরাদ এডির্নকে বাইরের সাহায্য থেকে বিচ্ছিন্ন করতে আকিঞ্জিদের ইস্তানবুলের সামনে পর্যন্ত পাঠালেন। ইস্তানবুল-এডির্ন পথের চোরলু, লুলেবুরগাজ ও বাবাএস্কি দুর্গ এবং দক্ষিণ থ্রেসের পথ সংযোগস্থল কেশান দখল হলো। এডির্নের আত্মসমর্পণ এই অবরোধ বলয় সম্পূর্ণ হওয়ার পর এলো।", "fb171002"]},
"OLAYLAR_EK:1361-01-01:0":{"b": ["দিদিমোতিখোনের দখল — মারিৎসা উপত্যকার উন্মুক্তি", "b59aee83"], "d": ["মারিৎসা উপত্যকার মূল দুর্গ দিদিমোতিখোন দখল হলো; এডির্ন বিজয়ের পথ এভাবে খুলল। গালিপোলি থেকে উত্তরে প্রসারিত করিডর সম্পূর্ণ না হলে এডির্নের দিকে অগ্রসর হওয়া সম্ভব ছিল না, তাই এই দুর্গ রুমেলি বিজয়ের ক্রমে এডির্নের আগে আসে। শহর কিছুকাল সুলতানদের রুমেলি সদর দপ্তর ছিল। দিদিমোতিখোন দখলকারী বাহিনী পরে কুলেলি বুর্গাজ (Pythion)-এর মতো ছোট দুর্গসহ মধ্য মারিৎসা অঞ্চলের পুরোটা নিয়ন্ত্রণে আনল।", "88f995b6"]},
"OLAYLAR_EK:1366-08-01:0":{"b": ["গালিপোলির হারানো (সাভয় ক্রুসেড)", "00e7e415"], "d": ["বাইজেন্টাইন সম্রাটের ভাই সাভয়ের আমাদেওর নৌবহর গালিপোলি দখল করে বাইজেন্টাইনদের হাতে তুলে দিল; রুমেলিতে অটোমানদের সেতুমুখ দশ বছর প্রণালীর ওপার থেকে পরিচালিত হলো। একই তারিখে হাতছাড়া হওয়া অন্যান্য বসতি: চিম্পে।", "b0c24ccd"]},
"OLAYLAR_EK:1371-09-26:0":{"b": ["চির্মেনের যুদ্ধ — মারিৎসা উপত্যকার নিয়ন্ত্রণ", "cd738d8d"], "d": ["সার্বীয় বেগদের সেনাবাহিনী রাতের হামলায় ছত্রভঙ্গ হলো; ম্যাসেডোনিয়া ও রোডোপের সার্বীয়/বুলগেরীয় স্থানীয় বেগরা একে একে অটোমানদের কর দিতে শুরু করল — সরাসরি বিজয় নয়, অধীনতার ঢেউয়ের সূচনা। অটোমান বর্ণনায় এই যুদ্ধ আলাদাভাবে «সির্প সিন্দিগি» নামে এবং 1364 সালে হাজি ইলবে এডির্ন পুনরুদ্ধারে আসা ক্রুসেডার বাহিনীর ওপর রাতের হামলা হিসেবে বর্ণিত; TDV জানায় ওই তারিখ ভুল এবং দুই বর্ণনা একই যুদ্ধের।", "7b2779cd"]},
"OLAYLAR_EK:1372-06-01:0":{"b": ["ফিলিবে ও স্তারা জাগোরার বিজয়", "e780c9ae"], "d": ["মারিৎসা উপত্যকার উজানের ফিলিবে ও তার উত্তরের স্তারা জাগোরা দখল হলো; বুলগেরীয় জারতন্ত্র করদ হলো। ফিলিবে-সোফিয়ার মধ্যবর্তী পাজারজিক ও ইহতিমান পথ চির্মেনের পর অধীন হওয়া স্থানীয় বেগদের হাতে রইল।", "b8131db8"]},
"OLAYLAR_EK:1373-05-01:0":{"b": ["বাইজেন্টাইন অধীনস্থ রাষ্ট্র: পঞ্চম ইওয়ানিস প্রথম মুরাদের সেনাবাহিনীতে (1371 চির্মেন বিজয়ের ফল)", "13ffe568"], "d": ["TDV অনুযায়ী 26 সেপ্টেম্বর 1371 চির্মেন (মারিৎসা) বিজয়ের পর বাইজেন্টাইন সাম্রাজ্য অটোমান কর্তৃত্ব স্বীকার করে, কর দিতে ও অটোমান সেনাবাহিনীতে সেবা করতে সম্মত হয়ে অধীনস্থ রাষ্ট্রের অবস্থায় পড়েছিল। সম্রাট পঞ্চম ইওয়ানিস এই বাধ্যবাধকতায় 1373 সালে প্রথম মুরাদের সেনাবাহিনীতে যোগ দিলেন; সে সময় ইস্তানবুলে রেখে যাওয়া ছেলে চতুর্থ আন্দ্রোনিকোস বুরসায় শাহজাদা সাভজি বেগের সঙ্গে মিলে পিতাদের বিরুদ্ধে বিদ্রোহ করলেন।", "3fe5b636"]},
"OLAYLAR_EK:1376-09-01:0":{"b": ["গালিপোলির পুনরুদ্ধার", "5f96c0a5"], "d": ["বাইজেন্টাইন সিংহাসন-বিবাদে অটোমান সমর্থন পাওয়া চতুর্থ আন্দ্রোনিকোস বিনিময়ে গালিপোলি ফিরিয়ে দিলেন; রুমেলি ও আনাতোলিয়ার মধ্যকার সেতু আবার গড়ে উঠল। একই তারিখে অন্তর্ভুক্ত অন্যান্য স্থান: চিম্পে।", "fc79cd5d"]},
"OLAYLAR_EK:1381-01-01:0":{"b": ["গেরমিয়ানের যৌতুক: কুতাহিয়ার অন্তর্ভুক্তি", "d6a6fe61"], "d": ["গেরমিয়ানোগলু সুলেইমান শাহের কন্যা দেভলেতশাহ খাতুনের সঙ্গে ইলদিরিম বায়েজিদের বিয়েতে কুতাহিয়া, সিমাভ, তাভশানলি ও এগ্রিগোজ যৌতুক হিসেবে অটোমানদের হাতে আসে — যুদ্ধ ছাড়া সম্প্রসারণের একটি ক্লাসিক উদাহরণ। একই তারিখে অন্তর্ভুক্ত অন্যান্য স্থান: আফিয়ন।", "3321bbba"]},
"OLAYLAR_EK:1381-06-01:0":{"b": ["হামিদ প্রদেশ ক্রয়: ইসপার্তার অন্তর্ভুক্তি", "4a1b6047"], "d": ["হামিদোগলু হুসেইন বে তাঁর বেগলিকের একটি অংশ (আকশেহির-বেইশেহির-ইসপার্তা) নগদ অর্থের বিনিময়ে প্রথম মুরাদের কাছে বিক্রি করেন; হামিদ প্রদেশের বাকি অংশ 1391 সালে ইলদিরিম দখল করবেন।", "d316dea5"]},
"OLAYLAR_EK:1383-09-19:0":{"b": ["সেরেসের বিজয়", "d4d28b60"], "d": ["পূর্ব ম্যাসেডোনিয়ার চাবি সেরেস দখল হলো; থেসালোনিকি অবরোধ বলয়ে ঢুকল। সোফিয়া-সেরেসের মধ্যবর্তী কিউস্তেন্দিল-পেত্রিচ-নেভ্রোকোপ-দ্রামা রেখা এই তারিখে তখনও সরাসরি যুক্ত হয়নি, পর্যায়ক্রমে 1370-এর দশক-1383 সময়ে অধীন, 1383-এর পর সরাসরি শাসনে এলো।", "573cc19c"]},
"OLAYLAR_EK:1385-09-01:0":{"b": ["সোফিয়ার বিজয়", "96d5f01f"], "d": ["বলকান পর্বতের পশ্চিম গিরিপথ নিয়ন্ত্রণে এলো; এই তারিখে সেরেস ইতিমধ্যে 1383 থেকে হাতে থাকায় থ্রেস-ম্যাসেডোনিয়া ভূখণ্ড অবিচ্ছিন্ন একটি সমগ্র গড়ছিল।", "f358b568"]},
"OLAYLAR_EK:1386-01-01:0":{"b": ["নিশের বিজয়", "77f5d632"], "d": ["মোরাভা উপত্যকার তালা নিশ দখলে সার্বীয় ডেসপটাত সরাসরি হুমকির মুখে পড়ল।", "15f52aaf"]},
"OLAYLAR_EK:1387-04-09:0":{"b": ["থেসালোনিকির প্রথম আত্মসমর্পণ", "96010ee9"], "d": ["দীর্ঘ অবরোধের পর শহর আত্মসমর্পণ করল (1403 সালে বাইজেন্টাইনদের ফেরত দেওয়া হবে, 1430 সালে চূড়ান্তভাবে বিজিত হবে)। একই তারিখে অন্তর্ভুক্ত অন্যান্য স্থান: কাভালা।", "5ef8bffd"]},
"OLAYLAR_EK:1387-06-08:0":{"b": ["অটোমান-জেনোয়া আহদনামা — 1352 সালের চুক্তির নবায়ন", "be11d17a"], "d": ["পেরা থেকে আসা জেনোয়ার দূতদের সঙ্গে ওরহান গাজির আমলের 1352 সালের বাণিজ্য চুক্তি নবায়ন করা হয়; দুই রাষ্ট্রের মধ্যে শুল্ক, বন্দিদের সঙ্গে আচরণ ও মুক্ত বাণিজ্যের বিধান নতুন করে স্থির হয়। এটি অটোমান ও জেনোয়াবাসীর মধ্যে আনুষ্ঠানিকভাবে জানা প্রথম বন্ধুত্ব ও বাণিজ্য আহদনামা বলে গণ্য হয় — এটি সামরিক মৈত্রী নয়, সম্পূর্ণ বাণিজ্যিক চুক্তি।", "46b0f65b"]},
"OLAYLAR_EK:1388-01-01:0":{"b": ["চান্দারলি আলী পাশার বুলগেরিয়া অভিযান: শুমেন ও রুসের দখল", "2781c3a9"], "d": ["বুলগেরীয় জারতন্ত্রের দানিউব তীরের দুর্গগুলো এক অভিযানে হস্তগত হলো; একই বছর বসনিয়ায় বিলেচায় পাওয়া পরাজয়ের সঙ্গে গুলিয়ে ফেলা উচিত নয় — এটি ছিল আলাদা রণাঙ্গনে সমকালীন সাফল্য। তার্নোভো ও ভিদিন তখনও ধরে রাখা শেষ বুলগেরীয় কেন্দ্র ছিল।", "d6eaf4cd"]},
"OLAYLAR_EK:1388-08-27:0":{"b": ["বিলেচার পরাজয়", "89ba0a64"], "d": ["বসনিয়ার দিকে যাওয়া আকিঞ্জি বাহিনী বিলেচায় ফাঁদে পড়ে নিশ্চিহ্ন হলো; এই প্রথম বড় বলকান বিপর্যয় কসোভোর দিকে যাওয়া মৈত্রীকে সাহস জোগাল।", "9960a7a5"]},
"OLAYLAR_EK:1390-01-01:0":{"b": ["পশ্চিম আনাতোলিয়ার বেগলিকগুলোর অন্তর্ভুক্তি: সারুহান, আইদিন, মেন্তেশে", "dcc33b71"], "d": ["তিনটি বেগলিক এক অভিযানেই অন্তর্ভুক্ত হয়: সারুহানোগলুদের কেন্দ্র মানিসা; আইদিনোগলুদের কেন্দ্র আইদিন (ইজমিরের উচ্চ দুর্গসহ, তবে বন্দর/নিম্ন দুর্গ তখনও সেন্ট জন নাইটদের হাতে — 1402 পর্যন্ত); মেন্তেশেওগলুদের কেন্দ্র মুগলা-মিলাস, এবং দাত্চা-বদরুম-মারমারিস-ফেথিয়ে উপকূলরেখাসহ। এজিয়ান উপকূল প্রথমবার এক হাতে একত্র হলো। একই তারিখে অন্তর্ভুক্ত অন্যান্য স্থান: সোকে।", "7f3094f2"]},
"OLAYLAR_EK:1392-01-01:0":{"b": ["তেকে প্রদেশের অন্তর্ভুক্তি: আন্তালিয়ার অন্তর্ভুক্তি", "fdbeee5c"], "d": ["ভূমধ্যসাগর উপকূলের তেকে প্রদেশ অটোমান ভূখণ্ডে যুক্ত হলো। তেকেওগলুরা হামিদোগলুদের থেকে বিচ্ছিন্ন একটি শাখা: ফেলেকুদ্দিন দুন্দার বে বিজিত আন্তালিয়া ভাই ইউনুস বেকে ছেড়ে দেন এবং 1321 সালের কাছাকাছি সময়ে আলাদা একটি বেগলিক জন্ম নেয়। তাই আন্তালিয়া ও তার আশপাশ মানচিত্রে 1321-এর পর হামিদোগলুদের নয়, তেকেওগলুদের রঙে দেখানো হয়। বেগলিকটি আঙ্কারা যুদ্ধের পর পুনরায় প্রতিষ্ঠিত হয় এবং চূড়ান্তভাবে কেবল 1423 সালে বিলুপ্ত হয়।", "09a83d97"]},
"OLAYLAR_EK:1392-01-06:0":{"b": ["ইউস্কুপের বিজয়", "9e5a1af5"], "d": ["ভার্দার ম্যাসেডোনিয়ার কেন্দ্র দখল করা হলো; ইউস্কুপ রুমেলির প্রধান সীমান্ত কেন্দ্রগুলোর একটিতে পরিণত হলো।", "8722b1dd"]},
"OLAYLAR_EK:1392-11-01:0":{"b": ["কাস্তামোনুর অন্তর্ভুক্তি", "876330ba"], "d": ["জান্দারোগলুদের কাস্তামোনু শাখা বিলুপ্ত করা হলো; সিনোপ শাখা অধীনস্থ করদ হিসেবে টিকে রইল। একই তারিখে অন্তর্ভুক্ত অন্যান্য স্থান: বার্তিন, সাফরানবোলু।", "34d8e600"]},
"OLAYLAR_EK:1393-06-17:0":{"b": ["তার্নোভোর পতন — বুলগেরিয়ার অন্তর্ভুক্তি", "ff666977"], "d": ["বুলগেরীয় জারতন্ত্রের রাজধানীর পতন ঘটল; বুলগেরিয়া সরাসরি অটোমান শাসনের অধীনে এলো। একই তারিখে অন্তর্ভুক্ত অন্যান্য স্থান: প্লেভেন, লভেচ।", "182028e2"]},
"OLAYLAR_EK:1393-06-17:1":{"b": ["লভেচ (Loveç) দুর্গ অটোমানদের হাতে গেল", "a55e87a0"], "d": ["বুলগেরীয় জার ইভান শিশমানের দুর্গগুলোর একটি লভেচ, তার্নোভো পতনের 1393 সালের অভিযানে শিশমানের অন্যান্য প্রদেশের সঙ্গে অটোমান ভূখণ্ডে যুক্ত হলো। সূত্র নিশ্চিত নয়: বিজয় এ বছরেই ঘটেছিল বলে «ধারণা করা হয়»।", "9430a123"]},
"OLAYLAR_EK:1393-09-01:0":{"b": ["দোব্রুজার অন্তর্ভুক্তি", "478e36f2"], "d": ["দানিউব ব-দ্বীপ পর্যন্ত বিস্তৃত দোব্রুজা অঞ্চল অন্তর্ভুক্ত হলো। একই তারিখে অন্তর্ভুক্ত অন্যান্য স্থান: সিলিস্ত্রা, কনস্তান্তা।", "05bdabb4"]},
"OLAYLAR_EK:1394-01-01:0":{"b": ["থেসালিতে অবতরণ", "8bec60dd"], "d": ["ইয়েনিশেহির (লারিসা) কেন্দ্রিক থেসালির সমভূমি অটোমান শাসনের অধীনে এলো। একই তারিখে অন্তর্ভুক্ত অন্যান্য স্থান: ত্রিকালা, ইজদিন (লামিয়া)।", "d9f2128c"]},
"OLAYLAR_EK:1394-01-01:1":{"b": ["ইস্তানবুলের কঠোর অবরোধ শুরু (অবরোধ ~1387 থেকে)", "0068bc04"], "d": ["ইলদিরিম বায়েজিদ ইস্তানবুলকে বিরতি দিয়ে দিয়ে দশ বছর অবরুদ্ধ রাখলেন; শহর কেবল তিমুরের এগিয়ে আসার কারণে রক্ষা পেল।", "504fcb33"]},
"OLAYLAR_EK:1394-10-10:0":{"b": ["রোভিনের যুদ্ধ — ওয়ালাচিয়া অভিযান", "343ae7a9"], "d": ["ওয়ালাচিয়ার ভয়েভোদ মির্চার সঙ্গে হওয়া রক্তক্ষয়ী ও ফলাফলে বিতর্কিত যুদ্ধের পর ওয়ালাচিয়া অটোমানদের কর দিতে সম্মত হলো; দানিউবের উত্তরে অধীনতার ব্যবস্থা গড়ে উঠল।", "dd69200f"]},
"OLAYLAR_EK:1395-01-01:0":{"b": ["নিকোপোলের বিজয়", "b9791717"], "d": ["ওয়ালাচিয়ানদের বিরুদ্ধে 1395 সালের রোভিনের যুদ্ধের পর ইলদিরিম বায়েজিদ দানিউবের তীরের নিকোপোল দুর্গ দখল করেন; কিছু বেনামি বুলগেরীয় কালানুক্রমিক গ্রন্থ বলে যে বিজয় ঘটে 3 জুন 1395 তারিখে। বিজয়ের তারিখ সূত্রগুলোতে এক নয়: TDV ইসলাম বিশ্বকোষের নিকোপোল যুদ্ধ নিবন্ধ জানায় যে বায়েজিদ 1394 সালের এক দানিউব অভিযানে সিলিস্ত্রা ও নিকোপোল দখল করেন। দুর্গ 1396 সালের বিখ্যাত ক্রুসেডে অবরুদ্ধ হবে, তবে পতিত হবে না। একই তারিখে অন্তর্ভুক্ত অন্যান্য স্থান: ওহরিড।", "bc450a9f"]},
"OLAYLAR_EK:1395-06-03:0":{"b": ["নিকোপোল দুর্গ অটোমানদের হাতে গেল", "327012c9"], "d": ["রোভিনের অভিযানের পর ইলদিরিম বায়েজিদ নিকোপোল দখল করলেন; অটোমান করদ হিসেবে সেখানে বসবাসকারী বুলগেরীয় জার ইভান শিশমান অপসারিত হলেন। অ্যাটলাসে নিকোপোল এই দিন থেকে বুলগেরীয় জারতন্ত্র থেকে অটোমানদের নামে লেখা।", "6e7d5207"]},
"OLAYLAR_EK:1395-08-01:0":{"b": ["আনাদোলু হিসারের নির্মাণ", "aa259b00"], "d": ["ইস্তানবুল অবরোধ সহায়তার জন্য প্রণালীর আনাতোলীয় তীরে গুজেলচে হিসার (আনাদোলু হিসার) নির্মিত হলো — প্রণালী নিয়ন্ত্রণের প্রথম স্থায়ী পদক্ষেপ।", "a1b2f889"]},
"OLAYLAR_EK:1396-10-01:0":{"b": ["ভিদিনের অন্তর্ভুক্তি", "ee1ae44b"], "d": ["নিকোপোলের বিজয়ের পর শেষ বুলগেরীয় রাজ্য ভিদিনও অন্তর্ভুক্ত হলো।", "28f4258d"]},
"OLAYLAR_EK:1397-07-01:0":{"b": ["কারামানের প্রথম অন্তর্ভুক্তি", "3cf07876"], "d": ["আকচায়ের বিজয়ে কারামানোগলুদের ভূখণ্ড প্রথমবার অটোমানদের সঙ্গে যুক্ত হলো (ফেত্রেতের সময় পুনঃপ্রতিষ্ঠিত হবে)।", "788bdca3"]},
"OLAYLAR_EK:1398-07-01:0":{"b": ["জানিক উপকূলের অন্তর্ভুক্তি: সামসুন", "af9c40fa"], "d": ["কাজি বুরহানুদ্দিন আকক্কোইউনলু কারায়ুলুক ওসমান বেগের হাতে বন্দি হওয়ায় সৃষ্ট শূন্যতায় ইলদিরিম বায়েজিদ প্রথমে কৃষ্ণ সাগর উপকূলের জানিক অঞ্চল অটোমান শাসনে আনেন। সামসুন ও তার আশপাশ এভাবে রাজবংশের প্রথম কৃষ্ণ সাগরের বন্দর হলো। অভ্যন্তরের সিভাস-তোকাত-কাইসেরি রেখা দুই সপ্তাহ পরে কাজি বুরহানুদ্দিন রাষ্ট্রের কার্যত ভেঙে পড়ার সঙ্গে অন্তর্ভুক্ত হবে।", "4b2f9a80"]},
"OLAYLAR_EK:1399-09-01:0":{"b": ["মালাত্যা দখল", "7cb6ae16"], "d": ["মামলুক সীমান্তের মালাত্যা দখল করা হলো — তিমুরের সঙ্গে উত্তেজনা বাড়ানো পদক্ষেপগুলোর একটি।", "3b7ba002"]},
"OLAYLAR_EK:1400-01-01:0":{"b": ["তিমুর মালাত্যা দখল করে কারায়ুলুক ওসমানকে দিলেন — তিমুর সরে গেলে দুলকাদিরোগলুরা তা ফিরিয়ে নিল", "ad2ce7d8"], "d": ["ইলদিরিম বায়েজিদ 1399 সালে দখল করা মালাত্যা দুলকাদিরোগলু নাসিরুদ্দিন মেহমেদকে ছেড়ে দিয়ে বুরসায় ফিরে গিয়েছিলেন। 1400 সালে আনাতোলিয়ায় প্রবেশ করে তিমুর প্রথমে সিভাস ও এলবিস্তান, তারপর মালাত্যা দখল করেন; শহর ও তার আশপাশ লুণ্ঠিত হয়, শাসনভার তিমুরের সঙ্গী কারায়ুলুক ওসমানকে দেওয়া হয়। তিমুর অঞ্চল ছাড়লে মালাত্যায় আবার দুলকাদিরোগলুরা কর্তৃত্ব করে; অটোমান কর্তৃত্ব এভাবে আঙ্কারার আগেই শেষ হয়ে যায়।", "5889cce9"]},
"OLAYLAR_EK:1403-06-01:0":{"b": ["সুলেইমান চেলেবি – বাইজেন্টাইন চুক্তি: থেসালোনিকি ফেরত", "cc503cc2"], "d": ["ফেত্রেতে রুমেলি শাসনকারী সুলেইমান চেলেবি বাইজেন্টাইন ও ল্যাটিন রাষ্ট্রগুলোর সঙ্গে চুক্তি করে থেসালোনিকি ও মিসিভ্রি পর্যন্ত কৃষ্ণ সাগর উপকূল বাইজেন্টাইনদের ছেড়ে দিলেন (TDV ফেত্রেত যুগ: গালিপোলি চুক্তি, ফেব্রুয়ারি 1403) — মানচিত্রে ইনেআদা, রেজভে ও আহতোপোল বাইজেন্টাইনদের হাতে যায়; মানচিত্রে থেসালোনিকি এই তারিখে অটোমানদের থেকে বেরিয়ে যায়।", "ac791637"]},
"OLAYLAR_EK:1416-05-29:0":{"b": ["গালিপোলির নৌ পরাজয় (ভেনিস)", "b71d4d68"], "d": ["ভেনিসের নৌবহর গালিপোলির সামনে অটোমান নৌবহরকে গুরুতরভাবে পরাজিত করল; প্রথম যুগের অটোমান নৌশক্তির সীমা দেখানো ঘটনা হলো।", "7166c255"]},
"OLAYLAR_EK:1421-08-15:0":{"b": ["ভুয়া মুস্তাফার বিদ্রোহ", "0ec43138"], "d": ["নিজেকে ইলদিরিমের ছেলে দাবি করা মুস্তাফা চেলেবি বাইজেন্টাইন সমর্থনে রুমেলিতে সালতানাত ঘোষণা করলেন; দ্বিতীয় মুরাদ 1422 সালে বিদ্রোহ দমন করে প্রতিদ্বন্দ্বীকে প্রাণদণ্ড দিলেন।", "9bae8d0d"]},
"OLAYLAR_EK:1422-06-10:0":{"b": ["দ্বিতীয় মুরাদের ইস্তানবুল অবরোধ", "4b9d9fba"], "d": ["বাইজেন্টাইনরা ভুয়া মুস্তাফাকে সমর্থন করায় দ্বিতীয় মুরাদ ইস্তানবুল অবরোধ করলেন; ভাই কুচুক মুস্তাফাকে আনাতোলিয়ায় বিদ্রোহী করে তোলায় অবরোধ তুলে নেওয়া হলো।", "bc254acf"]},
"OLAYLAR_EK:1423-09-14:0":{"b": ["থেসালোনিকির ভেনিসকে হস্তান্তর", "bfa6c4a0"], "d": ["অটোমান চাপের মুখে বাইজেন্টাইন গভর্নর শহরটি ভেনিসকে হস্তান্তর করলেন; সাত বছর চলা অটোমান-ভেনিস দ্বন্দ্ব শুরু হলো।", "da60fe5f"]},
"OLAYLAR_EK:1425-06-01:0":{"b": ["পশ্চিম আনাতোলিয়ার বেগলিকগুলোর পুনরায় অন্তর্ভুক্তি: মেন্তেশে ও আইদিন", "aca30a48"], "d": ["ফেত্রেত যুগে পুনঃপ্রতিষ্ঠিত দুই এজিয়ান বেগলিক দ্বিতীয় মুরাদের আমলে চূড়ান্তভাবে অটোমান ভূখণ্ডে যুক্ত হলো। TDV-এর মেন্তেশেওগলুরা নিবন্ধ অনুসারে দ্বিতীয় মুরাদ 827 হিজরিতে (1424) মেন্তেশে প্রদেশ দখল করেন এবং বেগলিকের প্রধান দুই ভাইকে বন্দি করান। আইদিনোগলুরা নিবন্ধ অনুসারে আনাতোলিয়ার বেইলারবেই হামজা বে পুনরায় অবাধ্য হওয়া জুনেইদ বেকে ধরিয়ে পরিবারসহ প্রাণদণ্ড দেন (829/1425-26) এবং আইদিন প্রদেশ অটোমানদের হাতে যায়। 1344 থেকে ইজমিরের বন্দর-দুর্গ ধরে রাখা সেন্ট জন নাইটরা তা 1402 সালে তিমুরের হাতে হারিয়েছিল, অঞ্চলটি আবার আইদিনোগলুদের নিয়ন্ত্রণে ফিরেছিল; এই অন্তর্ভুক্তিতে সেটিও অটোমানদের সঙ্গে যুক্ত হলো। তেকে প্রদেশ (আন্তালিয়া) এই বিষয়ের অন্তর্ভুক্ত নয়: তেকেওগলুরা 1423 সালে আলাদাভাবে বিলুপ্ত হয়েছিল। গেরমিয়ান অবশ্য 1429 সালে উইলের মাধ্যমে যুক্ত হবে।", "92fa8d97"]},
"OLAYLAR_EK:1429-01-01:0":{"b": ["গেরমিয়ানের উইলের মাধ্যমে অন্তর্ভুক্তি", "9eb86b77"], "d": ["নিঃসন্তান মারা যাওয়া গেরমিয়ান বে দ্বিতীয় ইয়াকুব তাঁর দেশ উইল করে অটোমানদের দিয়ে গেলেন — যুদ্ধহীন অন্তর্ভুক্তির পাঠ্যবইয়ে স্থান পাওয়া উদাহরণ। একই তারিখে অন্তর্ভুক্ত অন্যান্য স্থান: কারাহিসার-ই সাহিব (আফিয়ন)।", "9173c7b2"]},
"OLAYLAR_EK:1430-03-29:0":{"b": ["থেসালোনিকির চূড়ান্ত বিজয়", "bc021768"], "d": ["ভেনিসের শাসনাধীন শহর আক্রমণে দখল করা হলো; রুমেলির দ্বিতীয় বৃহত্তম বন্দর চূড়ান্তভাবে অটোমান হলো। একই তারিখে অন্তর্ভুক্ত অন্যান্য স্থান: কাসান্দ্রা।", "8853e257"]},
"OLAYLAR_EK:1430-10-09:0":{"b": ["ইয়ানিনার আত্মসমর্পণ", "ee45cb52"], "d": ["এপিরাসের কেন্দ্র ইয়ানিনা চুক্তির মাধ্যমে আত্মসমর্পণ করল।", "1aad46c0"]},
"OLAYLAR_EK:1439-08-27:0":{"b": ["স্মেদেরেভোর প্রথম দখল", "c11ca17d"], "d": ["তিন মাসের অবরোধে সার্বীয় ডেসপটাতের রাজধানী দখল হলো এবং সার্বিয়া প্রথমবার অন্তর্ভুক্ত হলো (1444 সালের এডির্ন-সেগেদিন চুক্তিতে ফেরত দেওয়া হবে)।", "3dc4dfe5"]},
"OLAYLAR_EK:1440-04-01:0":{"b": ["বেলগ্রেড অবরোধ (ব্যর্থ)", "3e05f425"], "d": ["ছয় মাস চলা প্রথম বড় বেলগ্রেড অবরোধ ফল দিল না; দুর্গ আশি বছর অটোমান অগ্রযাত্রার সামনে তালা হয়ে রইল।", "2a88be8a"]},
"OLAYLAR_EK:1443-11-24:0":{"b": ["ইজলাদির পরাজয় — 'দীর্ঘ অভিযান'", "97df1466"], "d": ["হুন্যাদি শীতের মাঝখানে বলকানে যে সেনাবাহিনী ঢুকিয়েছিলেন, তা নিশ ও সোফিয়া পেরিয়ে ইজলাদিতে পৌঁছল; অটোমান প্রতিরক্ষা কষ্টে টিকে রইল। এই পরাজয়ের আবহ এডির্ন-সেগেদিন শান্তিকে আলোচনার টেবিলে আনল।", "cf103982"]},
"OLAYLAR_EK:1444-06-12:0":{"b": ["এডির্ন-সেগেদিন চুক্তি", "0aa4e0de"], "d": ["দশ বছরের শান্তি: সার্বীয় ডেসপটাত ফেরত দেওয়া হলো, দানিউব সীমান্ত হিসেবে গৃহীত হলো। পোপের উসকানিতে কয়েক মাসের মধ্যে চুক্তি ভঙ্গ হওয়া ভার্নার বিপর্যয়ের পথ করে দিল।", "46b3ced6"]},
"OLAYLAR_EK:1444-08-15:0":{"b": ["স্মেদেরেভো ও সার্বীয় দুর্গগুলো সার্বিয়াকে ফেরত", "cda3cf9e"], "d": ["এডির্ন-সেগেদিন চুক্তির বিধান কার্যকর হলো: দ্বিতীয় মুরাদ 15 আগস্ট 1444 স্মেদেরেভো, তার চব্বিশটি গুরুত্বপূর্ণ দুর্গ ও দখলাধীন অন্যান্য সার্বীয় ভূমিসহ জুরাজ ব্রাঙ্কোভিচকে ফিরিয়ে দিলেন (TDV semendire); নিশ (TDV nis), আলাজাহিসার (TDV alacahisar), শেহিরকোই (TDV sehirkoy) ও প্রিস্তিনাও (TDV pristine) সার্বদের ছেড়ে দেওয়া হলো। ভিদিন সার্বীয় ভূমি না হওয়ায় ফেরতের অন্তর্ভুক্ত হয়নি — মানচিত্রে ভার্না বিজয়ের আশপাশে দেখা উত্তর-পশ্চিমের ভূখণ্ড ক্ষতির উৎস এটাই; কয়েক মাস পর ভার্নার পরাজয়ের সঙ্গে চুক্তি এমনিতেই অকার্যকর হবে।", "19c68a1f"]},
"OLAYLAR_EK:1452-08-31:0":{"b": ["রুমেলি হিসার সম্পূর্ণ — 'বোগাজকেসেন'", "480e8a76"], "d": ["সূত্র অনুযায়ী চার-পাঁচ মাসের অসাধারণ দ্রুত নির্মাণে সম্পূর্ণ হওয়া এই দুর্গের মাধ্যমে প্রণালীর নিয়ন্ত্রণ পুরোপুরি অটোমানদের হাতে গেল; কৃষ্ণ সাগর থেকে ইস্তানবুলে সাহায্যের পথ বন্ধ হলো। এটি অবরোধের কার্যত প্রথম পদক্ষেপ গণ্য হয়।", "1d84cd36"]},
"OLAYLAR_EK:1453-04-06:0":{"b": ["কনস্টান্টিনোপল অবরোধ শুরু", "8af50742"], "d": ["সেনাবাহিনী প্রাচীরের সামনে অবস্থান নিল; 54 দিন স্থায়ী অবরোধে বিশাল কামান প্রথমবার একটি রাজধানীর প্রাচীরের বিরুদ্ধে পদ্ধতিগতভাবে ব্যবহৃত হলো।", "6d71da31"]},
"OLAYLAR_EK:1453-04-22:0":{"b": ["জাহাজ স্থলপথে গোল্ডেন হর্নে নামানো হলো", "4f2ba07c"], "d": ["শিকলে বন্ধ গোল্ডেন হর্নে ঢুকতে না পারা নৌবহরের প্রায় 70টি জাহাজ তেল মাখানো কাঠের স্লিপারের ওপর দিয়ে গালাতার ঢাল পার করে এক রাতে গোল্ডেন হর্নে নামানো হলো; প্রতিরক্ষা দুই ফ্রন্টে ভাগ হলো।", "2eb65d41"]},
"OLAYLAR_EK:1456-06-04:0":{"b": ["এথেন্সের বিজয়", "4f0f1bb2"], "d": ["এথেন্সের ডাচি শেষ হলো; অ্যাক্রোপলিসে অটোমান পতাকা উড়ল। একই তারিখে অন্তর্ভুক্ত অন্যান্য স্থান: থিবস, লিভাদিয়া।", "a912625d"]},
"OLAYLAR_EK:1459-06-20:0":{"b": ["সার্বিয়ার অন্তর্ভুক্তি (স্মেদেরেভোর পতন)", "75fd0a62"], "d": ["সার্বীয় ডেসপটাতের রাজধানী স্মেদেরেভো আত্মসমর্পণ করল; সার্বিয়া একটি অটোমান সানজাকে পরিণত হলো।", "29bd2888"]},
"OLAYLAR_EK:1460-05-29:0":{"b": ["মোরিয়ার বিজয়", "7d5a3c18"], "d": ["মোরিয়া ডেসপটাত বিলুপ্ত হলো; উপদ্বীপ (ভেনিসীয় দুর্গ বাদে) অটোমান শাসনে এলো।", "14aba74c"]},
"OLAYLAR_EK:1461-06-01:0":{"b": ["সিনোপের অন্তর্ভুক্তি", "e03c2739"], "d": ["জান্দারোগলু সিনোপ যুদ্ধ ছাড়াই আত্মসমর্পণ করল; ত্রাবজোন অভিযানের পথ খুলল। একই তারিখে অন্তর্ভুক্ত অন্যান্য স্থান: কাস্তামোনু, বার্তিন, সাফরানবোলু। TDV-এর জান্দারোগলুরা নিবন্ধ বোলু, এফলানি ও তোসিয়াকেও 1461 সালে দখল হওয়া জান্দারোগলু বেগলিকের ভূখণ্ডের মধ্যে উল্লেখ করে; অ্যাটলাসে এই তিন স্থানও এই দিনে জান্দারোগলু থেকে অটোমানদের নামে লেখা।", "4ef62060"]},
"OLAYLAR_EK:1463-06-01:0":{"b": ["বসনীয় রাজ্যের পতন — ফাতিহের বসনিয়া অভিযান", "5362e3f2"], "d": ["শেষ বসনীয় রাজা স্তেপান তোমাশেভিচ (1461-1463) পশ্চিমের সমর্থনের ভরসায় কর দিতে অস্বীকার করায় করদ শাসক হিসেবে গণ্য হওয়া বন্ধ হলো এবং সুলতান ফাতিহ মেহমেদের নেতৃত্বাধীন সেনাবাহিনী এক অভিযানে বসনীয় রাজ্য বিলুপ্ত করল। রাজা ধৃত ও নিহত হলেন, রাজ্যের অবসান ঘটল এবং অঞ্চলে বসনিয়া সানজাক প্রতিষ্ঠিত হলো। তবে রাজ্যের পতন বসনিয়া বিজয়ের সমার্থক নয়। সমভূমিতে অটোমান শাসন আগেই পনেরো বছর ধরে ছিল — হোদিদেদ ও সারাইয়েভো সমভূমি 1448 সালে দখল হয়েছিল, ঈসা বেগের সীমান্ত বেগলিক রাজ্যের মাঝখানে গড়ে উঠেছিল। বিজয় 1463-তেও শেষ হয়নি: ফোচা 1465 সালে, লিভনো 1469 সালে, হার্জেগোভিনা ডাচি 1483 সালে, স্রেব্রেনিক বানাত 1512 সালে, উত্তরের ইয়াইচে ও বাঞ্জা লুকা কেবল মোহাচের পর 1528 সালে দখল করা সম্ভব হয় — হাঙ্গেরীয়রা 1463-র পর বসনিয়ার উত্তরে পঁয়ষট্টি বছর টিকে থাকা একটি বানাত গড়েছিল। এই তারিখে সরাসরি হাতবদল হওয়া স্থান ত্রাভনিক; ইয়াইচে এই তারিখে অটোমানদের নয়, হাঙ্গেরির হাতে গেছে।", "5ac16344"]},
"OLAYLAR_EK:1468-01-01:0":{"b": ["কারামানের চূড়ান্ত অন্তর্ভুক্তি", "f1dcecaa"], "d": ["কারামানোগলুদের কেন্দ্রীয় ভূখণ্ড চূড়ান্তভাবে যুক্ত হলো; অভ্যন্তরীণ বিবাদ 1470-এর দশক পর্যন্ত চলল। একই তারিখে অন্তর্ভুক্ত অন্যান্য স্থান: নিগদে, মোস্তার, বেইশেহির।", "da6cfd4c"]},
"OLAYLAR_EK:1470-07-12:0":{"b": ["এগ্রিবোজের বিজয়", "5c97daf3"], "d": ["এজিয়ানে ভেনিসের প্রধান ঘাঁটি এগ্রিবোজ (নেগ্রোপন্তে) পতিত হলো।", "189cc474"]},
"OLAYLAR_EK:1471-01-01:0":{"b": ["আলানিয়া, আনামুর ও সিলিফকের (ইচেল) অন্তর্ভুক্তি", "a0b9d461"], "d": ["কারামানোগলুদের অধীন ইচেল উপকূলরেখা (ভূমধ্যসাগরের আন্তালিয়া-মেরসিন অংশের পুরোটা) গেদিক আহমেদ পাশার নৌ অভিযানে যুক্ত হলো; সেলজুক যুগের কৌশলগত নৌঘাঁটির কারণে আলানিয়া গুরুত্বপূর্ণ ছিল।", "8302df58"]},
"OLAYLAR_EK:1478-01-15:0":{"b": ["নভগোরদের মস্কোর সঙ্গে সংযুক্তি", "bed87170"], "d": ["গ্র্যান্ড ডিউক তৃতীয় ইভান নভগোরদের জনসভার (ভেচে) প্রতীকী ঘণ্টা সরিয়ে নিলেন, স্থানীয় শাসকদের নিজের গভর্নরদের দিয়ে প্রতিস্থাপন করলেন এবং শহরকে কার্যত মস্কোর সঙ্গে যুক্ত করলেন; নভগোরদ স্বাধীন প্রজাতন্ত্র থাকা বন্ধ করল। নভগোরদের ভূখণ্ড বাল্টিক সাগর থেকে শ্বেত সাগর ও উরাল পর্যন্ত বিস্তৃত ছিল। অ্যাটলাসে এই দিন থেকে নভগোরদ, নভগোরদ প্রজাতন্ত্র থেকে মস্কোর নামে লেখা।", "65b660e7"]},
"OLAYLAR_EK:1479-01-25:0":{"b": ["ইস্তানবুল চুক্তি — আলবেনিয়া ও ইশকোদ্রা", "b09652f7"], "d": ["ষোলো বছরের অটোমান-ভেনিস যুদ্ধ শেষ হলো; ইশকোদ্রা ও আলবেনিয়ার উপকূল অটোমানদের হাতেই রইল। একই তারিখে অন্তর্ভুক্ত অন্যান্য স্থান: লিমনোস, সামোস, আজিওস এফস্ত্রাতিওস।", "bc2aebf2"]},
"OLAYLAR_EK:1480-08-11:0":{"b": ["ওত্রান্তো অবতরণ", "7916b89d"], "d": ["আপুলিয়ার (Pulya) উপকূলে নামা অটোমান বাহিনী ওত্রান্তো দুর্গ অবরোধ করে দখল করল; শহরে যুদ্ধ করে প্রবেশ করায় প্রতিরোধকারী নেতাদের একাংশকে মৃত্যুদণ্ড দেওয়া হয়, কিছুকে বন্দি করা হয়। চার্চের ঐতিহ্য নিহতদের প্রায় 800 জনের «ওত্রান্তোর শহীদ» হিসেবে স্মরণ করে; TDV এই সংখ্যার অতিরঞ্জনকে চার্চের প্রচারণা বলে অভিহিত করে। কেবল সালেন্তো উপদ্বীপের প্রান্তের দুর্গ ও তার সংকীর্ণ আশপাশ ধরে রাখা হয়; নেপলস রাজ্যের তারান্তো-ব্রিন্দিসি-লেচ্চে রেখার বাকি ভূখণ্ড হাতছাড়া হয়নি — ইতালিতে খোলা এই সেতুমুখ এক বছর টিকবে।", "0e1004b8"]},
"OLAYLAR_EK:1481-09-10:0":{"b": ["ওত্রান্তোর খালি করা", "37371bb0"], "d": ["ফাতিহ সুলতান মেহমেদের মৃত্যুতে (3 মে 1481) নতুন সাহায্যের আশা না থাকায় ওত্রান্তো গ্যারিসন নেপলসের উত্তরাধিকারী আলফোনসোর অবরোধের মুখে চুক্তির মাধ্যমে দুর্গ খালি করে দিল; ইতালিতে অটোমানদের একমাত্র সেতুমুখ এভাবে এক বছর পরে হাতছাড়া হলো।", "961ef9c3"]},
"OLAYLAR_EK:1500-08-09:0":{"b": ["মোদন ও করোনের বিজয়", "38b608c4"], "d": ["মোরিয়ায় ভেনিসের «দুই চোখ» মোদন ও করোন দখল হলো।", "a11c09d0"]},
"OLAYLAR_EK:1501-08-17:0":{"b": ["দুরাসের বিজয়", "1f231b98"], "d": ["1499-1503 অটোমান-ভেনিস যুদ্ধকালে মেহমেদ বেগের নেতৃত্বাধীন বাহিনী আদ্রিয়াটিকে ভেনিসের শেষ বড় আলবেনীয় বন্দর দুরাস দখল করল। ইশকোদ্রা (1479) ও ভলোরা (1417) পর এই বিজয়ে আলবেনিয়ার উপকূলরেখা সম্পূর্ণ অটোমান নিয়ন্ত্রণে এলো।", "ad635bca"]},
"OLAYLAR_EK:1515-09-15:0":{"b": ["পূর্ব আনাতোলিয়ার অন্তর্ভুক্তি", "e0cb8f8f"], "d": ["চালদিরানের পর দিয়ারবাকির ও তার আশপাশ যুক্ত হলো; কুর্দি বেগলিকগুলো ইদ্রিস-ই বিতলিসির হাত ধরে অটোমানদের সঙ্গে সংযুক্ত হলো।", "025d3ddc"]},
"OLAYLAR_EK:1526-07-27:0":{"b": ["ভারাদিন (পেত্রোভারাদিন) দুর্গের বিজয়", "abf392a5"], "d": ["মোহাচ অভিযানে বের হওয়া সেনাবাহিনী বেলগ্রেড থেকে হাঙ্গেরীয় ভূখণ্ডে প্রবেশ করল; ভারাদিনের প্রথমে বাইরের মহল্লাগুলো দখল হলো, চোদ্দ দিনের অবরোধের পর দুর্গও পতিত হলো। কানুনি পথের ধারের গ্রামগুলো না পোড়ানোর আদেশ দিলেন, কারণ সেগুলো এখন অটোমান ভূমি গণ্য হচ্ছিল।", "60a4ae4e"]},
"OLAYLAR_EK:1526-09-01:0":{"b": ["মোহাচের পর বুদিনের আত্মসমর্পণ — হাঙ্গেরীয় সিংহাসনে দুই রাজা", "9d3568a0"], "d": ["মোহাচ বিজয়ের পর বুদিনের দিকে অগ্রসর অটোমান সেনাবাহিনীর কাছে শহরের চাবি 11 সেপ্টেম্বর 1526 সুলতানের সামনে উপস্থাপন করা হলো; তবে কানুনি বুদিন ধরে রাখলেন না এবং বাহিনী ফিরিয়ে নিলেন। রাজাহীন হাঙ্গেরিতে অভিজাতরা দুজন আলাদা রাজা নির্বাচন করল: 10 নভেম্বর 1526 জানোশ সাপোলিয়াই, 17 ডিসেম্বর 1526 হাবসবার্গ প্রথম ফার্দিনান্দ। ফার্দিনান্দ আগস্ট 1527 সালে বুদিন দখল করেন। সাপোলিয়াইয়ের অটোমান আশ্রয়ে রাজা হিসেবে বুদিনে বসা 1529 সালের অভিযানে ঘটবে (1529 এন্ট্রি দেখুন), সরাসরি অটোমান শাসন 1541 সালে প্রতিষ্ঠিত হবে।", "d68817d3"]},
"OLAYLAR_EK:1526-11-10:0":{"b": ["জানোশ সাপোলিয়াই হাঙ্গেরীয় রাজা নির্বাচিত — অটোমানরা অধীনতার শর্তে তাঁর রাজ্য স্বীকার করল", "32bc6baf"], "d": ["মোহাচে রাজার মৃত্যুতে শূন্য হাঙ্গেরীয় সিংহাসনে অভিজাতদের একাংশ ট্রান্সিলভানিয়ার ভয়েভোদ জানোশ সাপোলিয়াইকে নির্বাচিত করল; সাপোলিয়াই সেকেশফেহেরভারে মুকুট পরলেন। বুদিন খালি করা অটোমানরা অঞ্চলটিকে বাফার হিসেবে রাখতে সাপোলিয়াইয়ের রাজ্য নিজেদের অধীন হওয়ার শর্তে স্বীকার করল। মানচিত্রে সাপোলিয়াইয়ের অধীন স্থানগুলো এই তারিখ থেকে অটোমানদের অধীন দেখায়।", "1d697cbd"]},
"OLAYLAR_EK:1526-12-17:0":{"b": ["প্রথম ফার্দিনান্দ হাঙ্গেরীয় রাজা ঘোষিত — পশ্চিম ও উত্তর হাঙ্গেরি হাবসবার্গ মুকুটে", "b3910a2f"], "d": ["হাবসবার্গ আর্কডিউক ফার্দিনান্দ বোনের দ্বিতীয় লাইওশের সঙ্গে বিয়ের ভিত্তিতে হাঙ্গেরীয় সিংহাসনে দাবি জানালেন এবং একাংশ অভিজাত তাঁকে রাজা ঘোষণা করল। হাঙ্গেরি এভাবে দুই রাজার মধ্যে বিভক্ত হলো; পশ্চিম ও উত্তর অংশ ফার্দিনান্দকে স্বীকার করল। ক্রোয়াট অভিজাতরা 1527-এর শুরুতে তাঁকে আলাদাভাবে নির্বাচন করল।", "1484af4c"]},
"OLAYLAR_EK:1530-01-01:0":{"b": ["দুই রাজার বিবাদ: এস্তেরগম হাবসবার্গ আশ্রয়ে, সেগেদিন সাপোলিয়াইয়ের অধীনে", "da92dee5"], "d": ["1526 থেকে দুই রাজার মধ্যে হাতবদল হওয়া এস্তেরগম, আর্চবিশপের নথিপত্র ও কোষাগারসহ উত্তরে সরে যাওয়ার পর হাবসবার্গ আশ্রয়ে গেল। একই বছর থেকে 1541 পর্যন্ত সেগেদিন সাপোলিয়াইয়ের কর্তৃত্বে রইল।", "4317e319"]},
"OLAYLAR_EK:1532-01-01:0":{"b": ["পেচুইয়ের মানুষ সাপোলিয়াইয়ের পক্ষে গেল", "3fc4e7f2"], "d": ["1528 সালে ফার্দিনান্দের কাছ থেকে বিশেষাধিকার পাওয়া পেচুই অল্প পরেই সাপোলিয়াইয়ের পক্ষে গেল; রাজা জানোশ 1533 সালে কিছুদিন শহরে ছিলেন। 1541 সালে বুদিনের পতনের সঙ্গে শহর আবার ফার্দিনান্দের দিকে ফিরল।", "af03d9f3"]},
"OLAYLAR_EK:1551-08-15:0":{"b": ["ত্রিপোলির বিজয়", "8c659986"], "d": ["সেন্ট জন নাইটদের কাছ থেকে ত্রিপোলি দখল হলো; উত্তর আফ্রিকার মধ্য উপকূল অটোমান হলো। একই তারিখে অন্তর্ভুক্ত অন্যান্য স্থান: মিসরাতা।", "f3a5310d"]},
"OLAYLAR_EK:1552-07-27:0":{"b": ["তেমেশভারের বিজয়", "e9fd4995"], "d": ["বানাত অঞ্চল দখল করে তেমেশভার বেইলারবেইলিক প্রতিষ্ঠিত হলো।", "1b99085d"]},
"OLAYLAR_EK:1574-08-25:0":{"b": ["তিউনিসের চূড়ান্ত বিজয়", "7bbd11bc"], "d": ["স্পেনীয়-হাফসি নিয়ন্ত্রণাধীন তিউনিস চূড়ান্তভাবে অটোমান শাসনে এলো; উত্তর আফ্রিকার রেখা সম্পূর্ণ হলো। একই তারিখে অন্তর্ভুক্ত অন্যান্য স্থান: কাইরুয়ান, গাবেস, সফাকস।", "a92c818a"]},
"OLAYLAR_EK:1600-10-20:0":{"b": ["কানিজসার বিজয়", "0c7b6aa3"], "d": ["দীর্ঘ যুদ্ধে কানিজসা দখল হলো; পরের বছর তিরিয়াকি হাসান পাশার প্রতিরক্ষা মহাকাব্যের রূপ পেল।", "12042d94"]},
"OLAYLAR_EK:1663-04-13:0":{"b": ["উইভার অভিযান শুরু — ফাজিল আহমেদ পাশা এডির্ন থেকে অস্ট্রিয়ার দিকে অগ্রসর", "306a86db"], "d": ["অস্ট্রিয়া ট্রান্সিলভানিয়া আক্রমণ করে সেকেলিহিদ ও কলোজভার দুর্গ দখল করায় ইস্তানবুল হাবসবার্গদের বিরুদ্ধে অভিযানের সিদ্ধান্ত নিল। প্রধান উজির কোপ্রুলুজাদে ফাজিল আহমেদ পাশা 13 এপ্রিল 1663 এডির্ন থেকে যাত্রা করলেন। বেলগ্রেডে অস্ট্রিয়ার শান্তি প্রস্তাব এলো, তবে ওসিয়েকের দুই আলোচনায় অটোমান শর্ত প্রত্যাখ্যাত হলো। বুদিনের পরামর্শসভায়ও লক্ষ্য উইভার স্থির হলো।", "f77c2f04"]},
"OLAYLAR_EK:1663-09-24:0":{"b": ["উইভারের বিজয়", "ce289470"], "d": ["উত্তর হাঙ্গেরির মূল দুর্গ উইভার দখল হলো; 'উইভারের সামনে তুর্কির মতো শক্তিশালী' বাগধারা ইউরোপীয় ভাষায় ঢুকে পড়ল। উইভারের পর নিত্রা ও লেভাও স্বল্প প্রতিরোধের পর আত্মসমর্পণ করল; দুটিই 1664 সালের বসন্তে দে সুশ পুনর্দখল করেন।", "80ef48fc"]},
"OLAYLAR_EK:1715-07-01:0":{"b": ["মোরিয়ার পুনরুদ্ধার", "9b6460f1"], "d": ["কার্লোভিৎসে ভেনিসকে ছেড়ে দেওয়া মোরিয়া এক অভিযানেই পুনরুদ্ধার হলো। একই তারিখে অন্তর্ভুক্ত অন্যান্য স্থান: পাত্রাস, নাফপাক্তোস।", "56dc13ce"]},
"OLAYLAR_EK:1717-08-18:0":{"b": ["বেলগ্রেডের দ্বিতীয়বার হারানো — যুবরাজ ইউজিনের অবরোধ", "6a194354"], "d": ["ভারাদিনের পরাজয় ও তেমেশভার হারানোর পর যুবরাজ ইউজিন বেলগ্রেড অবরোধ করলেন; শহর রক্ষায় আসা সাহায্যকারী বাহিনীও পরাজিত হলে দুর্গ আত্মসমর্পণ করল। কার্লোভিৎসের পর 1690 সালে পুনরুদ্ধার হওয়া শহর এভাবে আবার হাতছাড়া হলো এবং দানিউব প্রতিরক্ষা রেখা ভেঙে পড়ল। বেলগ্রেড কেবল বাইশ বছর পরে, 1739 সালের বেলগ্রেড চুক্তিতে ফিরে পাওয়া সম্ভব হবে। একই তারিখে হাতছাড়া হওয়া অন্যান্য বসতি: স্মেদেরেভো। অ্যাটলাস আরও গ্রোচকা (Grocka) ও ইয়াগোদিনা (Jagodina) অঞ্চল এই দিনে হাবসবার্গের নামে লেখে (অঞ্চলের দিন; বসতি পর্যায়ে দিন সূত্রে নেই, ঘোষিত আনুমানিকতা); মেহাদিয়া অবশ্য 27 আগস্ট 1717 তারিখে হাবসবার্গের হাতে যায় (Bánlaky 0019/1715)।", "83c63cd6"]},
"OLAYLAR_EK:1788-12-17:0":{"b": ["ওজির পতন", "90a67a6c"], "d": ["কৃষ্ণ সাগরের উত্তরের মূল দুর্গ ওজি রক্তক্ষয়ী আক্রমণে রাশিয়ার হাতে গেল; শহরের মানুষকে তরবারির আঘাতে হত্যা করা হলো।", "9d37026c"]},
"OLAYLAR_EK:1812-05-28:0":{"b": ["বুখারেস্ট চুক্তি — বেসারাবিয়ার হারানো", "932da4d6"], "d": ["1806-1812 রুশ যুদ্ধ শেষ করা চুক্তিতে প্রুতের পূর্বদিক (বেসারাবিয়া) রাশিয়াকে ছেড়ে দেওয়া হলো। একই তারিখে হাতছাড়া হওয়া অন্যান্য বসতি: আক্কেরমান, কিলিয়া, হোতিন, বেন্ডের, ইসমাইল। অ্যাটলাস আরও বেসারাবিয়ার মধ্যকার কিশিনেভ (Chișinău), বেলৎসি (Bălți), কাহুল (Cahul) ও ওরহেইকে একই দিনে মোলদোভা (অটোমানের অধীনস্থ) থেকে রাশিয়ায় গেছে বলে ধরে। সোরোকাও (Soroca) একই দিনে রাশিয়ায় যায়।", "b5921c60"]},
"OLAYLAR_EK:1829-09-14:0":{"b": ["এডির্ন চুক্তি", "b3a8fe4c"], "d": ["রুশ সেনাবাহিনী এডির্নে প্রবেশ করা যুদ্ধের শেষে দানিউব ব-দ্বীপ হারানো হলো; গ্রিসের স্বায়ত্তশাসন/স্বাধীনতা কার্যত স্বীকৃত হলো। একই তারিখে হাতছাড়া হওয়া অন্যান্য বসতি: ব্রাইলা, আনাপা, আখালৎসিখে। চুক্তি ভূমি ফিরিয়ে দিলেও দখল সঙ্গে সঙ্গে শেষ করেনি: ওয়ালাচিয়া-মলদোভা ও সিলিস্ত্রা যুদ্ধের ক্ষতিপূরণ পরিশোধ না হওয়া পর্যন্ত জামিন হিসেবে রুশ প্রশাসনে রইল — মানচিত্রে এসব স্থান 1829-এর পরও দখলাধীন দেখানোর কারণ এটাই।", "d09a34fb"]},
"OLAYLAR_EK:1830-10-17:0":{"b": ["সার্বিয়াকে স্বায়ত্তশাসনের ফরমান — বংশানুক্রমিক নেজ-পদ ও গ্যারিসনের শর্ত", "6a5d901d"], "d": ["এডির্ন চুক্তির সার্বিয়া সংক্রান্ত বিধান অনুযায়ী জারি হওয়া হাত্ত-ই হুমায়ুন মিলোশ ওব্রেনোভিচকে বংশানুক্রমিক নেজ স্বীকৃতি দিল এবং সার্বিয়াকে অভ্যন্তরীণ বিষয়ে স্বাধীন, বাইরে অটোমানদের সঙ্গে যুক্ত একটি স্বায়ত্তশাসিত প্রিন্সিপালিটিতে পরিণত করল। বিধান: নেজ-পদ পিতা থেকে পুত্রে যাবে, বার্ষিক কর নির্দিষ্ট হারে দেওয়া হবে, সার্বীয় সভা নিজস্ব অভ্যন্তরীণ প্রশাসন গড়বে, চার্চ স্বায়ত্তশাসিত থাকবে; বিনিময়ে বেলগ্রেড, স্মেদেরেভো, সাবাক, বোগুরদেলেন ও ফেথুলইসলাম দুর্গে অটোমান গ্যারিসন থাকবে। এই দ্বৈত কাঠামো 1867 সালে গ্যারিসন সরিয়ে নেওয়া পর্যন্ত চলল। মানচিত্রে বেলগ্রেড শহর এই তারিখে স্বায়ত্তশাসিত সার্বিয়ায় যুক্ত হয়; কালেমেগদান দুর্গ 1867 পর্যন্ত অটোমান গ্যারিসনে দেখানো হয়।", "b71abc85"]},
"OLAYLAR_EK:1878-06-04:0":{"b": ["সাইপ্রাস ব্রিটিশ প্রশাসনে ছেড়ে দেওয়া", "423da3ee"], "d": ["রুশ হুমকির বিরুদ্ধে মৈত্রীর বিনিময়ে সাইপ্রাসের প্রশাসন ব্রিটেনকে হস্তান্তর করা হলো; আইনত তা অটোমান ভূখণ্ডই রইল। একই তারিখে হাতছাড়া হওয়া অন্যান্য বসতি: নিকোসিয়া, ফামাগুস্তা, কিরেনিয়া, লিমাসল, লার্নাকা (Tuzla), পাফোস, মোরফু (Morphou), আক্রোতিরি, এপিস্কোপি, দেকেলিয়া (Dhekelia); অর্থাৎ পুরো দ্বীপ।", "d1abea1c"]},
"OLAYLAR_EK:1881-07-02:0":{"b": ["থেসালি গ্রিসকে ছেড়ে দেওয়া", "ac614d24"], "d": ["বার্লিন কংগ্রেসের সিদ্ধান্ত অনুযায়ী থেসালি ও আর্তা অঞ্চল গ্রিসকে হস্তান্তর করা হলো। একই তারিখে হাতছাড়া হওয়া অন্যান্য বসতি: আর্তা, ইয়েনিশেহির (লারিসা), ত্রিকালা, ইজদিন (লামিয়া)। এই হস্তান্তরে ভোলোস, কালাম্বাকা ও কার্দিৎসা (থেসালি) গ্রিসে যায়।", "9fc28546"]},
"OLAYLAR_EK:1885-09-18:0":{"b": ["পূর্ব রুমেলির বুলগেরিয়ায় যোগদান", "ee43f137"], "d": ["স্বায়ত্তশাসিত পূর্ব রুমেলি প্রদেশ এক অভ্যুত্থানে বুলগেরিয়ার সঙ্গে যুক্ত হলো; বাবে আলি এই fait accompli মেনে নিল। এই মিলনে পূর্ব রুমেলির পুরোটা (স্তারা জাগোরা, পাজারজিক, সিলিভ্রিয়া, খাসকোভো, বুর্গাস, আইতোস, এলহোভো) বুলগেরিয়া প্রিন্সিপালিটিতে গেল।", "7fe3cc42"]},
"OLAYLAR_EK:1897-05-17:0":{"b": ["দোমোকোসের রণক্ষেত্রের যুদ্ধ", "9c6f29a5"], "d": ["1897 সালের অটোমান-গ্রিক যুদ্ধে সেনাবাহিনী দোমোকোসে নিষ্পত্তিমূলক বিজয় পেল; কূটনৈতিক চাপে ভূখণ্ড লাভ সীমিত রইল।", "aff8be0b"]},
"OLAYLAR_EK:1898-12-22:0":{"b": ["ক্রিটকে স্বায়ত্তশাসন", "2e764881"], "d": ["অটোমান-গ্রিক যুদ্ধ অটোমান বিজয়ে শেষ হওয়া সত্ত্বেও ব্রিটেন, রাশিয়া, ফ্রান্স ও ইতালি 18 ডিসেম্বর 1897 ক্রিটের স্বায়ত্তশাসন ঘোষণা করল; দ্বীপটি অটোমান আধিপত্যে নিরপেক্ষ ও স্বায়ত্তশাসিত প্রদেশ হবে। 6 নভেম্বর 1898-এর পর ক্যান্ডিয়া ও কিসামোসে তুর্কি পতাকা আর ওঠেনি; গ্রিক রাজার পুত্র প্রিন্স জর্জ অসাধারণ কমিশনার হিসেবে 22 ডিসেম্বর 1898 দায়িত্ব নেওয়ায় ক্রিট কার্যত অটোমান শাসনের বাইরে গেল (আনুষ্ঠানিকভাবে 1913-তে পৃথক হয়)। একই তারিখে হাতছাড়া হওয়া অন্যান্য বসতি: ক্যান্ডিয়া (ক্রিট), খানিয়া।", "bc35b2a6"]},
"OLAYLAR_EK:1908-10-05:0":{"b": ["বুলগেরিয়ার স্বাধীনতা ও বসনিয়ার দখল", "393feaa4"], "d": ["সাংবিধানিক বিশৃঙ্খলার মধ্যে বুলগেরিয়া স্বাধীনতা ঘোষণা করল, অস্ট্রিয়া-হাঙ্গেরি বসনিয়া-হার্জেগোভিনা অন্তর্ভুক্ত করল। এই ঘোষণায় বুলগেরিয়া প্রিন্সিপালিটির সমস্ত ভূখণ্ড (ভার্না, শুমেন, রুসে, বুর্গাস, সিলিভ্রিয়া প্রভৃতি) স্বাধীন বুলগেরিয়া রাজ্য হলো।", "b7f0bb26"]},
"OLAYLAR_EK:1913-07-21:0":{"b": ["এডির্নের পুনরুদ্ধার", "536e5599"], "d": ["দ্বিতীয় বলকান যুদ্ধে সেনাবাহিনী মারিৎসা পার হয়ে যুদ্ধ ছাড়াই এডির্ন পুনরুদ্ধার করল। একই তারিখে অন্তর্ভুক্ত অন্যান্য স্থান: কিরক্লারেলি, তেকিরদাগ।", "e5420880"]},
"OLAYLAR_EK:1916-04-29:0":{"b": ["কুত আল-আমারার বিজয়", "98b972bc"], "d": ["কুতে অবরুদ্ধ ব্রিটিশ ডিভিশনের কমান্ডার তাঁর 13 হাজার সৈন্যসহ আত্মসমর্পণ করলেন — প্রথম বিশ্বযুদ্ধের সবচেয়ে বড় অটোমান বিজয়গুলোর একটি।", "20105888"]},
"OLAYLAR_EK:1917-03-11:0":{"b": ["বাগদাদের পতন", "2c18a816"], "d": ["383 বছরের অটোমান বাগদাদ ব্রিটিশ সেনাবাহিনীর হাতে গেল। একই তারিখে হাতছাড়া হওয়া অন্যান্য বসতি: কারবালা।", "4add66da"]},
"OLAYLAR_EK:1917-12-09:0":{"b": ["জেরুজালেমের পতন", "94067617"], "d": ["401 বছরের অটোমান জেরুজালেম প্রতিরক্ষা ছাড়াই আত্মসমর্পণ করা হলো।", "f2738a38"]},
"OLAYLAR_EK:1918-10-01:0":{"b": ["দামেস্কের পতন", "ed177b68"], "d": ["ফিলিস্তিন রণাঙ্গনের ভেঙে পড়ায় দামেস্ক খালি করা হলো; সিরিয়ায় চার শতকের অটোমান শাসন শেষ হলো। একই তারিখে হাতছাড়া হওয়া অন্যান্য বসতি: হামা, হোমস।", "ff6aea3f"]},
"OLAYLAR_EK:1919-01-10:0":{"b": ["মদিনার আত্মসমর্পণ", "76b505f6"], "d": ["যুদ্ধবিরতির 72 দিন পর 'মরুভূমির বাঘ' ফখরুদ্দিন পাশার প্রতিরোধ সুলতানের ইচ্ছায় শেষ হলো; হিজাজের শেষ অটোমান ইউনিট অস্ত্র সমর্পণ করল।", "06b180d9"]},
"OLAYLAR_EK:1919-05-15:0":{"b": ["ইজমির দখল", "e32e5e77"], "d": ["গ্রিক সেনাবাহিনী ইজমিরে অবতরণ করল; প্রথম গুলিতে শুরু হওয়া প্রতিরোধ জাতীয় সংগ্রামের সলতে জ্বালিয়ে দিল। আইদিন অবশ্য 27 মে 1919 দখল হয় (আলাদা এন্ট্রি)।", "4cc27e6b"]},
"OLAYLAR_EK:1920-03-16:0":{"b": ["ইস্তানবুলের আনুষ্ঠানিক দখল", "a8e98ada"], "d": ["মিত্রশক্তি ইস্তানবুল আনুষ্ঠানিকভাবে দখল করল, মেজলিস-ই মেবুসান ভেঙে দেওয়া হলো; সংসদ সদস্যরা আঙ্কারার দিকে গেলেন।", "09ed005b"]},
"OLAYLAR_EK:1921-10-13:0":{"b": ["কার্স চুক্তি", "bb32d4e0"], "d": ["তুরস্কের গ্র্যান্ড ন্যাশনাল অ্যাসেম্বলি ও ককেশাস প্রজাতন্ত্রগুলোর মধ্যে পূর্ব সীমান্ত বর্তমান রূপে আঁকা হলো।", "fe736259"]},
"OLAYLAR_ILIRYA0072:1779-01-01:0":{"b": ["সউদি-ওয়াহহাবি বাহিনীর হাইল আমিরাত দখল — প্রশাসন আবদা গোত্রের ইবনে আলী পরিবারের হাতে ছিল", "2d29ceb9"], "d": ["প্রথম সউদি রাষ্ট্রের বাহিনী যখন হাইল আমিরাত দখল করলো তখন শহরের প্রশাসন শাম্মার গোত্রের আবদা শাখার ইবনে আলী পরিবারের হাতে ছিল। এই পরিবার 1835 সালে আবদুল্লাহ ইবনে রশিদের আমিরাত দখল পর্যন্ত হাইল শাসন করলো; রশিদি রাজবংশ কেবল সেই তারিখে প্রতিষ্ঠিত হলো। অ্যাটলাসে হাইল এ পর্যন্ত 1836 সাল পর্যন্ত মালিকহীন দেখাচ্ছিল, অথচ সূত্র 1820 সালে শহরের আমিরকে নামসহ উল্লেখ করে।", "bc2aa4ea"]},
"OLAYLAR_ILIRYA0072:1806-01-01:0":{"b": ["কভারনার দ্বীপপুঞ্জের নেপোলিয়নের ইতালি রাজ্যে এবং বোকা কোতোরস্কার রুশ শাসনে যাওয়া", "c5e411c8"], "d": ["পোজুন চুক্তির পর কভারনার দ্বীপপুঞ্জ — দালমাতিয়ার ভিন্ন — সরাসরি ফ্রান্সে নয়, নেপোলিয়নের ইতালি রাজ্যের সঙ্গে যুক্ত হলো; তারা ইলিরীয় প্রদেশগুলোতে ঢুকলো কেবল 1809 সালে। বোকা কোতোরস্কায় অস্ট্রীয় শাসন শেষ হলো এবং 1806-1807 সালে রুশ শাসন প্রতিষ্ঠিত হলো; বোকা ফ্রান্সের হাতে গেল কেবল 1807 সালে। এই দুটি পার্থক্য অ্যাটলাসের একটি 'ফ্রান্স' জানালায় ধরা যায় না।", "ec06d97d"]},
"OLAYLAR_ILIRYA0072:1806-02-01:0":{"b": ["দালমাতিয়ার ফরাসি শাসনে যাওয়া — পোজুন (ব্রাতিস্লাভা) চুক্তির বাস্তবায়ন", "00bfe4f6"], "d": ["26 ডিসেম্বর 1805 পোজুন (ব্রাতিস্লাভা/প্রেসবুর্গ) চুক্তি অস্ট্রিয়াকে ইস্ট্রিয়া, দালমাতিয়া ও সমগ্র আদ্রিয়াটিক দ্বীপপুঞ্জ ত্যাগ করতে বাধ্য করলো। ফ্রান্স 1806 সালের ফেব্রুয়ারিতে কার্যত প্রশাসন গ্রহণ করলো; জাদার জেনারেল প্রভিডিটরের কেন্দ্র হিসেবে থাকলো এবং 1806-1810 সালে এই দায়িত্ব ভেনিসীয় ভিচেনৎসো দান্দোলো পালন করলেন। দালমাতিয়া 1809 সালের শনব্রুন চুক্তির পর ইলিরীয় প্রদেশগুলোর সঙ্গে যুক্ত হলো। 1797 সাল থেকে চলা প্রথম অস্ট্রীয় শাসন এভাবে শেষ হলো — অ্যাটলাসে এই সময়কাল এ পর্যন্ত নিরবচ্ছিন্ন অস্ট্রীয় দেখা যাচ্ছিল।", "b8a55f1c"]},
"OLAYLAR_ILIRYA0072:1813-01-01:0":{"b": ["অস্ট্রিয়ার ইলিরীয় প্রদেশ ও দালমাতিয়া পুনরুদ্ধার — নেপোলিয়নীয় শাসনের অবসান", "1b2ac942"], "d": ["1813 সালের শেষে হাবসবুর্গ বাহিনী সাভা নদীর দক্ষিণের অঞ্চল পুনরুদ্ধার করলো এবং পুরনো সীমান্ত সংগঠন আবার প্রতিষ্ঠিত হলো; অস্ট্রীয় সেনাবাহিনী 1813 সালের অক্টোবরে ইস্ট্রিয়ায় প্রবেশ করলো। কার্লোভাৎস সেই তারিখের পর অস্ট্রীয় ইলিরীয় রাজ্যের অংশ হলো। দালমাতিয়ায় ফরাসি শাসনের কালও 1813 সালে শেষ হলো। অঞ্চলের অস্ট্রিয়ার প্রতি অধিকার 1814 প্যারিস শান্তি ও 1815 ভিয়েনা কংগ্রেসের সিদ্ধান্তে আনুষ্ঠানিকভাবে নিশ্চিত হলো। এই অভিযানের মাধ্যমে ভিলাখ, তারভিজিও, গোরিৎসিয়া, গ্রাদিস্কা ও পুলা (ইলিরীয় প্রদেশ) 1813 সালের শেষে অস্ট্রিয়ার কাছে ফিরে এলো।", "bf1e49a8"]},
"OLAYLAR_SENKRON_0930:1298-01-01:0":{"b": ["মারাশ মামলুকদের হাতে গেল — আলেপ্পোর নায়েব বিলবান আত-তাবাহি আর্মেনীয়দের কাছ থেকে ফিরিয়ে নিলেন", "03171265"], "d": ["1258 সাল থেকে কিলিকিয়ার আর্মেনীয় রাজ্যের হাতে থাকা মারাশ 1293 সালে সুলতান খলিলের আর্মেনীয়দের সঙ্গে চুক্তিতে অল্প সময়ের জন্য মামলুকদের হাতে গিয়েছিল, তাদের সরে যাওয়ার পর আবার আর্মেনীয়দের হাতে পড়ে। 697 (1298) সালে মামলুকদের আলেপ্পো নায়েব বিলবান আত-তাবাহি শহর ফিরিয়ে নেন। মারাশ এরপর দুলকাদিরদের উত্থান পর্যন্ত মামলুক ভূমি হিসেবে থাকে।", "8fd31b13"]},
"OLAYLAR_SENKRON_0930:1372-01-01:0":{"b": ["বাইজেন্টাইন সাম্রাজ্য অটোমানদের করদ রাষ্ট্র হল", "615df998"], "d": ["চিরমেন বিজয়ের (1371) পর বাইজেন্টাইন সম্রাট পঞ্চম ইওয়ানেস 1372 সালের শীতে প্রথম মুরাদের করদ হতে সম্মত হন: বার্ষিক কর দেবেন এবং সুলতানের অভিযানে সৈন্য দেবেন। বাইজেন্টাইন এই তারিখ থেকে 1403 পর্যন্ত অটোমানদের অধীন সামন্ত রাষ্ট্র থাকে; ইলদিরিম বায়েজিদের 1391 সালের অবরোধ করের পরিমাণ বাড়ায়। আঙ্কারা পরাজয়ের পর সুলেমান চেলেবির সঙ্গে হওয়া গেলিবোলু চুক্তি (1403) বাইজেন্টাইনকে করমুক্ত করে; 1424 সালে দ্বিতীয় মুরাদের সঙ্গে চুক্তিতে কর আবার শুরু হয়।", "e3c816ac"]},
"OLAYLAR_SENKRON_0930:1399-09-01:0":{"b": ["ইলদিরিম বায়েজিদ বারকুকের মৃত্যুর পর বেসনি, দারেন্দে ও দিভরিগিকে অটোমান ভূমিতে যুক্ত করলেন", "8e57d7e6"], "d": ["মামলুক সুলতান বারকুকের মৃত্যুর (জুন 1399) পর মামলুক রাষ্ট্রের প্রশাসনিক কাজ বিগড়ে গেলে ইলদিরিম বায়েজিদ ইউফ্রেটিস অববাহিকায় নেমে মালাত্যার সঙ্গে বেসনি (বেহিসনি), দারেন্দে ও দিভরিগিকে অটোমান ভূমিতে যুক্ত করেন। এর আগে কাজি বুরহানুদ্দিনের 1398 সালের গ্রীষ্মের মৃত্যুর পর সিভাস অটোমানদের হাতে এসেছিল। দিভরিগি 1391 সাল থেকে মামলুক কর্তৃত্বে ছিল এবং আলেপ্পো প্রদেশের অধীন একটি অগ্রবর্তী ঘাঁটি ছিল। অটোমান শাসন এখানে বেশি দিন টেকেনি: ঘনিয়ে আসা তৈমুরের হুমকিতে দিভরিগি 1401 সালে আবার মামলুকদের দেওয়া হয়, শহরের চূড়ান্তভাবে অটোমান শাসনে আসা 1516 সালের মারজ দাবিকের পর।", "ec7cd171"]},
"OLAYLAR_SENKRON_0930:1400-08-01:0":{"b": ["তৈমুরের সিভাস ও মালাত্যা অভিযানের সময় বেসনি মামলুকদের হাতে গেল", "4853da9a"], "d": ["ইলদিরিম বায়েজিদ 1398 সালে সিভাস, দারেন্দে ও মালাত্যার সঙ্গে নেওয়া বেসনি 1400 সালে তৈমুর সিভাস ও মালাত্যা নেওয়ার সময় মামলুকদের হাতে যায়। তৈমুর 27 সেপ্টেম্বর 1400 তারিখে তীব্র অবরোধের পর বেসনিও দখল করেন; সেই অঞ্চল থেকে সরে গেলে বেসনি আবার মামলুক কর্তৃত্বে আসে এবং 1516 সালের আগস্টে সুলতান প্রথম সেলিম নেওয়া পর্যন্ত (দুলকাদির একটি মধ্যবর্তী পর্ব ছাড়া) মামলুকদের হাতে থাকে।", "0ead96f9"]},
"OLAYLAR_SENKRON_0930:1401-01-01:0":{"b": ["দিভরিগি তৈমুরের হুমকিতে আবার মামলুকদের দেওয়া হল", "97196b1f"], "d": ["ইলদিরিম বায়েজিদ 1398 সালে মামলুকদের কাছ থেকে নেওয়া দিভরিগি তৈমুর আনাতোলিয়ার কাছে এলে 1401 সালে আবার মামলুকদের ছেড়ে দেওয়া হয়। তাই তৈমুরের সিভাস ধ্বংসের (1400) পর দিভরিগি মানচিত্রে মামলুক রঙে দেখা যায়; একই মাসগুলোতে বায়েজিদ পূর্বে এরজিনজান ও কেমাহ নিচ্ছিলেন, অর্থাৎ মামলুক ভূমি অটোমানদের পশ্চিমের (সিভাস) ও উত্তর-পূর্বের (কেমাহ) ভূমির মাঝে থেকে যায়। দিভরিগি কেবল 1516 সালের মারজ দাবিকের পর চূড়ান্তভাবে অটোমানদের হাতে যায়।", "3f13d015"]},
"OLAYLAR_SENKRON_0930:1414-01-01:0":{"b": ["মামলুক সুলতান শেখ আন্তেপ ও দারেন্দে দুলকাদিরদের কাছ থেকে ফিরিয়ে নিলেন", "f90c9508"], "d": ["দুলকাদিরদের অটোমানদের সঙ্গে বন্ধুত্বে উদ্বিগ্ন মামলুক সুলতান শেখ 1414 সালে অভিযানে নামেন; আগে নিজের ইচ্ছায় দুলকাদিরদের দেওয়া আন্তেপ ও দারেন্দে ফিরিয়ে নেন।", "9f9b94e1"]},
"OLAYLAR_SENKRON_0930:1418-01-01:0":{"b": ["দুলকাদিরোগ্লু মেহমেদ বেগ দারেন্দে ফিরিয়ে নিলেন, বেসনিও নিজের ভূমিতে যুক্ত করলেন", "df914dcb"], "d": ["মামলুকদের 1414 সালে নেওয়া দারেন্দে দুলকাদিরোগ্লু মেহমেদ বেগ 1418 সালে ফিরিয়ে নেন এবং বেসনিও নিজের ভূমিতে যুক্ত করেন।", "d469f850"]},
"OLAYLAR_SENKRON_0930:1436-01-01:0":{"b": ["মামলুকরা আন্তেপে দুলকাদিরদের হারাল; বেসনি মামলুক শাসনে ফিরল (আনুমানিক)", "72742430"], "d": ["মামলুক সেনাবাহিনী 1436 সালে আন্তেপে দুলকাদিরদের পরাজিত করে, মেহমেদ বেগ আকদাগে সরে যান। বেসনির মামলুকদের হাতে ফেরার বছর সূত্রে লেখা নেই; বেসনি 1418 সালে দুলকাদিরে যুক্ত হয়েছিল, 1465 সালে শেহসুভার বেগ তা মামলুকদের কাছ থেকে নেওয়ার আগে মামলুকে ফিরেছিল। অ্যাটলাস বেসনিকে প্রতিবেশী কেন্দ্র আন্তেপের এই পরাজয়ের সঙ্গে একত্রে (ঘোষিত আনুমানিকতা) মামলুকদের ফিরিয়ে দেয়।", "dc3b71ff"]},
"OLAYLAR_SENKRON_0930:1467-01-01:0":{"b": ["দুলকাদিরোগ্লু শেহসুভার বেগ বেসনি মামলুকদের কাছ থেকে নিলেন (আনুমানিক)", "843f0fc4"], "d": ["বিজেতা সুলতান মেহমেদ কর্তৃক দুলকাদির বেগ নিযুক্ত শেহসুভার বেগ (1465-1472) মামলুকদের হাতে থাকা বেসনি, গের্গের, বিরেজিক ও রুমকালে দখল করেন; মামলুকরা 1467 সালের শরতে তুর্নাদাগে এবং 1468 সালের বসন্তে আন্তেপের কাছে পরাজিত হয়।", "c812ae2a"]},
"OLAYLAR_SENKRON_0930:1471-01-01:0":{"b": ["আমির ইয়েশবেক শেহসুভার বেগকে পরাজিত করলেন; বেসনি মামলুক শাসনে ফিরল (আনুমানিক)", "4d856aee"], "d": ["1471 সালের বসন্তে আমির ইয়েশবেক সাভরন খালে শেহসুভার বেগকে পরাজিত করেন; মামলুকরা কাদিরলি ও কোজান ফিরে নেয়। শেহসুভার 1472 সালে কায়রোতে মৃত্যুদণ্ডপ্রাপ্ত হন, মামলুকরা শাহবুদাককে আবার বেগ করে। বেসনিও এই প্রত্যাবর্তনে মামলুক শাসনে আসে (টিডিভি besni: 'পঞ্চদশ শতকের শেষের দিকে আবার মামলুকদের হাতে গেল')।", "3ba3c319"]},
"OLAYLAR_SENKRON_0930:1550-09-15:0":{"b": ["ফার্দিনান্দের বাহিনী সোলনক ধরে রাখল ও সুরক্ষিত করল", "6c8416e6"], "d": ["অটোমানরা তিসার উপর সোলনকে দুর্গ গড়ার প্রস্তুতি নিচ্ছিল, তখন প্রথম ফার্দিনান্দের বাহিনী এগিয়ে গেল: 1550 সালের সেপ্টেম্বরের মাঝামাঝি সোলনক দখল করে এবং অক্টোবরের মাঝামাঝি দুর্গ রক্ষাযোগ্য করা হয়। এভাবে ইজাবেলার ভূমির অংশ সোলনক ট্রান্সিলভানিয়ার ফার্দিনান্দের কাছে যাওয়ার এক বছর আগে হাবসবুর্গ হাতে যায়; অটোমানরা দুর্গ 1552 সালে নেয়।", "eea8389b"]},
"OLAYLAR_SENKRON_0930:1551-07-26:0":{"b": ["ট্রান্সিলভানিয়া হাবসবুর্গ শাসনে গেল: কলোজসভার পরিষদ ইজাবেলার ত্যাগ স্বীকার করল", "8458a566"], "d": ["মার্তিনুজ্জির ফার্দিনান্দের সঙ্গে চুক্তির পর রানি ইজাবেলা ছোট রাজা যানোস জিগমন্দের পক্ষে 19 জুন 1551 তারিখে সাসশেবেশ দুর্গে তাঁর উপর চাপিয়ে দেওয়া ত্যাগপত্রে স্বাক্ষর করেন। 26 জুলাই কলোজসভারে সমবেত ট্রান্সিলভানিয়া পরিষদ এই ত্যাগ এবং রাজা ফার্দিনান্দের কর্তৃত্ব স্বীকার করে; জেনারেল কাস্তালদোর হাবসবুর্গ সেনাবাহিনী ট্রান্সিলভানিয়া বেলগ্রেডে (গিউলাফেহেরভার) প্রবেশ করে। এভাবে অটোমান-অধীন ট্রান্সিলভানিয়া পাঁচ বছর স্থায়ী হাবসবুর্গ শাসনে যায়।", "d8d0aad9"]},
"OLAYLAR_SENKRON_0930:1556-03-12:0":{"b": ["ট্রান্সিলভানিয়ায় হাবসবুর্গ শাসনের অবসান: ট্রান্সিলভানিয়া আবার অটোমান-অধীন ভয়েভোদালিক হল", "721a482a"], "d": ["যানোস জিগমন্দের কম বয়সের কারণে তাঁর অভিভাবক নিযুক্ত ক্রোয়াট বংশোদ্ভূত যাজক মার্তিনুজ্জির (ফ্রাতের গিয়র্গি) হাত দিয়ে হাবসবুর্গরা 1551 সালে ট্রান্সিলভানিয়ায় কর্তৃত্ব নিতে চেয়েছিল; ট্রান্সিলভানিয়া বেলগ্রেড (গিউলাফেহেরভার), কলোশভার, ব্রাশ্যো ও সেগেসভার পাঁচ বছর হাবসবুর্গ শাসনে ছিল। অটোমানরা এ অবস্থা রোধ করে এবং ট্রান্সিলভানিয়া আবার নিজেদের অধীন করদ ভয়েভোদালিক হয়। ট্রান্সিলভানিয়া এরপর ষোড়শ ও সপ্তদশ শতকে প্রায় 150 বছর অভ্যন্তরীণ বিষয়ে ব্যাপক স্বায়ত্তশাসন এবং বৈদেশিক বিষয়ে ইস্তানবুলের প্রতি আনুগত্যের মর্যাদা ধরে রাখে।", "0566dd84"]},
"OLAYLAR_SENKRON_0930:1557-01-01:0":{"b": ["ভারাদ, হুস্ত ও তোকাই সাপোলিয়াইয়ের পক্ষে গেল", "587c782d"], "d": ["ইজাবেলা ও যানোস জিগমন্দের 1556 সালে ট্রান্সিলভানিয়ায় ফেরার পর সাপোলিয়াই সমর্থকরা 1556 সালে নাজভারাদ অবরোধ করে। 1557 সালে উচ্চ তিসার অভিজাতরা সবচেয়ে গুরুত্বপূর্ণ রাজকীয় দুর্গ — ভারাদ, হুস্ত ও তোকাই — দখল করে; ফার্দিনান্দের হাতে কেবল গিউলা ও ভিলাগোশ থাকে। ভারাদ এরপর ট্রান্সিলভানিয়া প্রিন্সিপালিটির দুর্গ হয় এবং 1660 সালে অটোমানরা নেওয়া পর্যন্ত তাই থাকে।", "3f850e28"]},
"OLAYLAR_SENKRON_0930:1565-02-01:0":{"b": ["শভেন্দি সাতমার নিলেন — ট্রান্সিলভানিয়ার উত্তর প্রান্ত হাবসবুর্গের হাতে গেল", "2256bb27"], "d": ["1561 সালে বালাশ্শা মেনিয়ের্তের পক্ষ বদলে হাবসবুর্গের কাছে যাওয়া সাতমার বাথরি ইস্তভান 1564 সালের শরতে আকস্মিক হামলায় ফিরিয়ে ট্রান্সিলভানিয়ায় যুক্ত করেছিলেন। হাবসবুর্গ অধিনায়ক লাজারুস ফন শভেন্দি 1565 সালের ফেব্রুয়ারিতে পাল্টা অভিযানে নামেন: তোকাই 9 ফেব্রুয়ারি, সেরেন্চ চার দিন পর পতন হয় এবং সাতমার প্রায় বিনা প্রতিরোধে সাম্রাজ্যিক বাহিনীর হাতে যায়।", "8735c789"]},
"OLAYLAR_SENKRON_0930:1605-01-21:0":{"b": ["বচকাইয়ের বাহিনী সাতমার নিল", "e93b098b"], "d": ["বচকাই বিদ্রোহ উত্তর-পূর্ব হাঙ্গেরিতে ছড়িয়ে পড়লে গিউলাফি অবরোধ করা সাতমার 21 জানুয়ারি 1605 তারিখে দখল করেন। 23 জুন 1606 তারিখের ভিয়েনা শান্তি সাতমার প্রদেশ আজীবন বচকাইকে ছেড়ে দেয়; পুরুষ উত্তরাধিকারী না থাকায় 29 ডিসেম্বর 1606 তারিখে বচকাইয়ের মৃত্যুতে প্রদেশ রাজ্যে ফিরে যায়।", "a7cde19a"]},
"OLAYLAR_SENKRON_0930:1606-12-29:0":{"b": ["বচকাই ইস্তভানের মৃত্যু — সাতমার প্রদেশ রাজ্যে ফিরল", "3721bb9b"], "d": ["ট্রান্সিলভানিয়ার প্রিন্স বচকাই ইস্তভান 29 ডিসেম্বর 1606 তারিখে কাশাতে মারা যান। ভিয়েনা শান্তি (23 জুন 1606) সাতমারসহ প্রদেশগুলো তাঁকে আজীবন, পুরুষ উত্তরাধিকারী না থাকলে রাজ্যে ফেরার শর্তে ছেড়ে দিয়েছিল; এই বিধানে সাতমার প্রদেশ হাবসবুর্গ হাঙ্গেরীয় রাজ্যে ফিরে যায়। ট্রান্সিলভানিয়া নতুন প্রিন্সের খোঁজে নামে।", "bbe08ca4"]},
"OLAYLAR_SENKRON_0930:1619-11-01:0":{"b": ["বেথলেন গাবর সাতমার প্রদেশ নিজের নিয়ন্ত্রণে নিলেন", "80263da1"], "d": ["বেথলেন গাবরের 1619 সালের শরতের হাঙ্গেরি অভিযানে সাতমার প্রদেশ ট্রান্সিলভানিয়ার প্রিন্সের নিয়ন্ত্রণে আসে; নভেম্বর 1619 তারিখে তিনি প্রদেশকে চিঠিতে সম্বোধন করছিলেন। 23 জানুয়ারি 1620 তারিখের প্রাথমিক চুক্তি ও নিকোলসবুর্গ শান্তি সাতমারসহ সাতটি প্রদেশ আজীবন বেথলেনকে ছেড়ে দেয়। বেথলেনের মৃত্যুর (15 নভেম্বর 1629) পর প্রদেশগুলো রাজ্যে ফেরত 30 মার্চ 1630 তারিখে সম্পূর্ণ হয়।", "76c6a30b"]},
"OLAYLAR_SENKRON_0930:1630-03-30:0":{"b": ["বেথলেন গাবরের সাত প্রদেশ রাজ্যে ফেরত সম্পূর্ণ", "31b5968f"], "d": ["নিকোলসবুর্গ শান্তি সাতমারসহ উচ্চ হাঙ্গেরির সাতটি প্রদেশ বেথলেন গাবরকে আজীবন ছেড়ে দিয়েছিল। বেথলেনের 15 নভেম্বর 1629 তারিখের মৃত্যুর পর প্রদেশগুলো রাজ্যে ফেরত 30 নভেম্বর 1629 নির্দেশে শুরু হয়ে 30 মার্চ 1630 তারিখে সম্পূর্ণ হয়।", "dd97dafd"]},
"OLAYLAR_SENKRON_0930:1644-02-01:0":{"b": ["প্রথম রাকোৎসি গিয়র্গি সাতমার নিয়ে নিলেন", "f398635b"], "d": ["ট্রান্সিলভানিয়ার প্রিন্স প্রথম রাকোৎসি গিয়র্গির 1644 সালের অভিযানে সাতমারের জার্মান সেনানিবাস রাকোৎসির সেবায় চলে আসে এবং দুর্গ ট্রান্সিলভানিয়ার হাতে আসে। 16 ডিসেম্বর 1645 তারিখের লিনৎস শান্তি ট্রান্সিলভানিয়ার সিংহাসনে একজন রাকোৎসি থাকা পর্যন্ত দুর্গ রাকোৎসি উত্তরাধিকারীদের ছেড়ে দেয়।", "17240548"]},
"OLAYLAR_SENKRON_0930:1664-05-03:0":{"b": ["নিত্রা হারানো — দ্য সুশ দুর্গ ফিরিয়ে নিলেন", "c71bf012"], "d": ["1663 সালে উইভার (ঊজভার) বিজয়ের পর স্বল্প প্রতিরোধে আত্মসমর্পণ করা নিত্রা সাম্রাজ্যিক অধিনায়ক দ্য সুশ 15 এপ্রিল 1664 তারিখে অবরোধ করেন; দুর্গ 3 মে 1664 তারিখে আত্মসমর্পণ করে। ভাসভার চুক্তি দখল করা স্থানগুলো যে অবস্থায় ছিল সেভাবেই রেখে দেওয়ায় উইভার অটোমানদের হাতে থাকে এবং নিত্রা হাবসবুর্গ হাতে থাকে।", "b1d01f51"]},
"OLAYLAR_SENKRON_0930:1664-06-14:0":{"b": ["লেভা হারানো", "f311920e"], "d": ["দ্য সুশ নিত্রার পর 9 জুন 1664 তারিখে লেভা অবরোধ করেন; 13 জুন আত্মসমর্পণ-চুক্তি স্বাক্ষরিত হয় এবং দুর্গ 14 জুন তারিখে সাম্রাজ্যিক বাহিনীর হাতে ছিল। 19 জুলাই 1664 তারিখের লেভা (গারামসেন্টবেনেদেক) যুদ্ধ মালিকানা বদলায়নি; হাবসবুর্গের লেভা ও নিত্রা ধরে রাখা দিয়ে শেষ হয়।", "7fe0a206"]},
"OLAYLAR_SENKRON_0930:1676-09-19:0":{"b": ["দরোশেঙ্কো চিহিরিন সামোইলোভিচের কাছে সমর্পণ করলেন", "3b538237"], "d": ["অটোমান আশ্রয়ে থাকা ডান তীরের হেটম্যান পেত্রো দরোশেঙ্কো রাজধানী চিহিরিন 19 সেপ্টেম্বর 1676 তারিখে বাম তীরের হেটম্যান সামোইলোভিচ ও রুশ বাহিনীর কাছে সমর্পণ করেন। অটোমানরা দরোশেঙ্কোকে অপসারণ করে তাঁর জায়গায় ইউরি খমেলনিৎস্কিকে আনে; চিহিরিনের রুশ সেনানিবাস সরাতে 1677 সালের অবরোধ ব্যর্থ হয়, দুর্গ কেবল 21 আগস্ট 1678 তারিখে নেওয়া হয়।", "cccf7b79"]}
});
